export const VM_SCRIPT_SOURCES: BuildInputs['vmScripts'] = {"orca-sandbox-start":"#!/usr/bin/env bash\n# Starts orcad for this boot (idempotent) and prints its recipe line:\n# {\"schemaVersion\":1,\"pairingCode\":\"orca://pair?...\",\"projectRoot\":\"/vercel/sandbox/project\"}\n# Env from the control plane: ORCA_SANDBOX_ID, ORCA_PUBLIC_WSS, optional ORCA_REPO_URL/ORCA_REPO_REF,\n# ORCA_GITHUB_PLACEHOLDER, ORCA_SECRET_ENV (`NAME=<base64>` lines: org/personal/repo secrets for\n# orcad and its agents), ORCA_SHARE_PROXY_KEY (this session's share-link proxy key, port 6769).\n# Never prints anything else on stdout's last line.\n# With ORCA_READY_VIA=file it prints {\"schemaVersion\":1,\"readyFile\":\"<path>\"} instead and the control\n# plane reads the offer with the files API: the provider keeps command stdout as logs, not files.\n# Managed env for every process orcad starts: ORCA_IS_CLOUD=1, ORCA_SANDBOX_ID, ORCA_ROOT_PATH,\n# ORCA_WORKTREE_PATH, ORCA_WORKSPACE_PATH, ORCA_WORKSPACE_NAME, ORCA_DEFAULT_BRANCH, ORCA_PORT and the\n# CONDUCTOR_* names imported Conductor scripts read.\nset -euo pipefail\numask 077\nORCA_HOME=/opt/orca\nSTATE=\"$HOME/.orca-sandbox\"\nPROJECT=/vercel/sandbox/project\nmkdir -p \"$STATE\"\nexec 9>\"$STATE/start.lock\"\nflock -w 60 9\n# Background children close fd 9 (`9>&-`): an orcad that inherited it would hold the lock for its whole\n# life and every later start (resume of a running sandbox, a retried create) would wait out the 60 s.\n\n# orcad only lists a project once a client registers it (the desktop does on connect), so API, MCP,\n# routine and phone sessions saw no repo. Register the workspace project at every start, in the\n# background (ready is not delayed); `repo add` of an already-registered path is a no-op error.\nregister_project() {\n  [ -x \"$ORCA_HOME/bin/orca\" ] && [ -d \"$PROJECT\" ] || return 0\n  local kind=() name=()\n  [ -e \"$PROJECT/.git\" ] || kind=(--kind folder)\n  # The checkout lives at .../project; name it after the repository (owner/name.git -> name).\n  if [ -n \"${ORCA_REPO_URL:-}\" ]; then\n    local base=\"${ORCA_REPO_URL%/}\"\n    base=\"${base##*/}\"\n    base=\"${base%.git}\"\n    [ -n \"$base\" ] && name=(--display-name \"$base\")\n  fi\n  setsid \"$ORCA_HOME/bin/orca\" repo add --path \"$PROJECT\" \"${kind[@]}\" \"${name[@]}\" --json \\\n    >\"$STATE/register-project.log\" 2>&1 </dev/null 9>&- &\n}\n\nprint_ready() {\n  if [ \"${ORCA_READY_VIA:-}\" = file ]; then\n    printf '{\"schemaVersion\":1,\"readyFile\":\"%s\"}\\n' \"$STATE/ready.json\"\n  else\n    tail -n 1 \"$STATE/ready.json\"\n  fi\n}\n# Command stderr is kept by the provider: strip injected values and credential shapes from log tails.\nredact_log() {\n  local text kv value\n  text=\"$(cat)\"\n  for kv in ${agent_env[@]+\"${agent_env[@]}\"}; do\n    value=\"${kv#*=}\"\n    if [ \"${#value}\" -ge 8 ]; then\n      text=\"${text//\"$value\"/[REDACTED]}\"\n    fi\n  done\n  printf '%s\\n' \"$text\" | sed -E \\\n    -e 's#orca://[^[:space:]]+#[REDACTED_PAIRING]#g' \\\n    -e 's#(gh[pousr]_|github_pat_|sk-|vc[kpiar]_)[A-Za-z0-9._-]{16,}#[REDACTED_TOKEN]#g' \\\n    -e 's#eyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}#[REDACTED_JWT]#g' \\\n    -e 's#(Authorization|authorization):[[:space:]]*[A-Za-z]+[[:space:]]+[^[:space:]]+#\\1: [REDACTED]#g'\n}\n\nnode=\"$(find \"$ORCA_HOME/runtime/runtimes\" -type f -name node | head -n 1)\"\n\n# Share-link proxy (port 6769): answers only requests the control plane signed with this session's\n# key, so its public route is useless on its own. The key goes in on stdin (printf is a builtin), so\n# it never appears in any argv or in the proxy's /proc/<pid>/environ.\nstart_share_proxy() {\n  [ -n \"${ORCA_SHARE_PROXY_KEY:-}\" ] && [ -x \"$ORCA_HOME/bin/orca-share-proxy\" ] || return 0\n  if [ \"$(cat \"$STATE/share-proxy.boot\" 2>/dev/null || true)\" = \"$boot_id\" ] \\\n    && kill -0 \"$(cat \"$STATE/share-proxy.pid\" 2>/dev/null || echo 0)\" 2>/dev/null; then\n    return 0\n  fi\n  printf '%s' \"$ORCA_SHARE_PROXY_KEY\" | env -i HOME=\"$HOME\" LANG=C.UTF-8 PATH=/usr/bin:/bin \\\n    setsid \"$node\" \"$ORCA_HOME/bin/orca-share-proxy\" >\"$STATE/share-proxy.log\" 2>&1 9>&- &\n  echo $! >\"$STATE/share-proxy.pid\"\n  printf '%s' \"$boot_id\" >\"$STATE/share-proxy.boot\"\n}\n\nboot_id=\"$(cat /proc/sys/kernel/random/boot_id)\"\nstart_share_proxy\nunset ORCA_SHARE_PROXY_KEY\nif [ \"$(cat \"$STATE/boot-id\" 2>/dev/null || true)\" = \"$boot_id\" ] && [ -s \"$STATE/ready.json\" ] \\\n  && kill -0 \"$(cat \"$STATE/orcad.pid\" 2>/dev/null || echo 0)\" 2>/dev/null; then\n  print_ready\n  exit 0\nfi\n# Resume = reboot from disk: locks and pids from the previous session name dead processes.\nrm -f \"$STATE/ready.json\" \"$STATE/orcad.pid\"\nprintf '%s' \"$boot_id\" >\"$STATE/boot-id\"\n\nif [ -n \"${ORCA_GIT_EXTRAHEADER:-}\" ]; then\n  # Every github.com request carries the placeholder; the egress policy swaps in a 1h repo token.\n  git config --global http.https://github.com/.extraheader \"$ORCA_GIT_EXTRAHEADER\"\nfi\n# Commits outside a teammate's turn (or before any member connected GitHub) need an author too.\ngit config --global user.email >/dev/null 2>&1 || git config --global user.email 'cloud@users.noreply.onorca.dev'\ngit config --global user.name >/dev/null 2>&1 || git config --global user.name 'Orca Cloud'\n# First boot clones while orcad starts (orcad only needs the directory to exist); ready waits for both.\nclone_pid=''\nif [ ! -d \"$PROJECT\" ]; then\n  mkdir -p \"$PROJECT\"\n  if [ -n \"${ORCA_REPO_URL:-}\" ]; then\n    git clone --quiet ${ORCA_REPO_REF:+--branch \"$ORCA_REPO_REF\"} -- \"$ORCA_REPO_URL\" \"$PROJECT\" 2>\"$STATE/clone.log\" 9>&- &\n    clone_pid=$!\n  fi\nfi\n\n# The clone may still be running here, so the name comes from the URL; the default branch is\n# filled in lazily by the session-env shell hook once the clone exists.\nif [ -n \"${ORCA_REPO_URL:-}\" ]; then\n  workspace_name=\"$(basename \"${ORCA_REPO_URL%/}\" .git)\"\nelse\n  workspace_name=\"$(basename \"$(git -C \"$PROJECT\" remote get-url origin 2>/dev/null || echo \"$PROJECT\")\" .git)\"\nfi\n# One workspace per VM: its preview ports start at 3000 (Conductor allots CONDUCTOR_PORT..+9).\nmanaged_env=(\n  ORCA_IS_CLOUD=1\n  ORCA_ROOT_PATH=\"$PROJECT\" ORCA_WORKTREE_PATH=\"$PROJECT\" ORCA_WORKSPACE_PATH=\"$PROJECT\"\n  ORCA_WORKSPACE_NAME=\"$workspace_name\" ORCA_PORT=3000\n  CONDUCTOR_IS_CLOUD=1\n  # Agent CLIs are pinned by the image (smoke-tested); a self-update mid-session can break a running agent.\n  DISABLE_AUTOUPDATER=1\n  CONDUCTOR_ROOT_PATH=\"$PROJECT\" CONDUCTOR_WORKSPACE_PATH=\"$PROJECT\"\n  CONDUCTOR_WORKSPACE_NAME=\"$workspace_name\" CONDUCTOR_PORT=3000\n)\n\nagent_env=()\nif command -v google-chrome >/dev/null; then\n  # Orca's browser automation and agent browser tools use the image's headless Chrome.\n  agent_env+=(\"ORCA_BROWSER_EXECUTABLE=$(command -v google-chrome)\")\nfi\nif [ -n \"${ORCA_GITHUB_PLACEHOLDER:-}\" ]; then\n  # The egress layer swaps the placeholder for a short-lived GitHub token; none lives in the VM.\n  agent_env+=(\"GH_TOKEN=$ORCA_GITHUB_PLACEHOLDER\" \"GITHUB_TOKEN=$ORCA_GITHUB_PLACEHOLDER\")\nfi\n\nsecret_names=()\nif [ -n \"${ORCA_SECRET_ENV:-}\" ]; then\n  # Secrets live only in memory: orcad's process env and a tmpfs file new shells re-read\n  # (orca-sandbox-env), never under $HOME or the project, so the stop snapshot never carries them.\n  # Resolved per start (and per edit) by the control plane: no image rebuild, no restart.\n  while IFS= read -r line; do\n    name=\"${line%%=*}\" b64=\"${line#*=}\" # not IFS='=': read would strip base64 padding\n    case \"$name\" in '' | *[!A-Z0-9_]* | [0-9]* | ORCA_* | PATH | HOME | LD_* | DYLD_*) continue ;; esac\n    agent_env+=(\"$name=$(printf '%s' \"$b64\" | base64 -d)\")\n    secret_names+=(\"$name\")\n  done < <(printf '%s\\n' \"$ORCA_SECRET_ENV\") # a pipe, not a here-string temp file\nfi\n# Always rewrite the file, so a resume with fewer secrets drops the old names too.\n\"$ORCA_HOME/bin/orca-sandbox-env\" >/dev/null || echo 'session env file unavailable; secrets apply at boot only' >&2\nunset ORCA_SECRET_ENV\n\n# Agent CLIs installed with the image's npm (codex, gemini, ...) are `#!/usr/bin/env node` scripts:\n# terminals need that node on PATH, not only orcad's bundled runtime.\nsystem_node=\"$(command -v node 2>/dev/null || echo \"$node\")\"\nenv -i HOME=\"$HOME\" USER=\"$(id -un)\" LANG=C.UTF-8 TERM=xterm-256color \\\n  PATH=\"$ORCA_HOME/tools/bin:$ORCA_HOME/bin:$(dirname \"$system_node\"):/usr/local/bin:/usr/bin:/bin\" \\\n  ORCA_USER_DATA=\"$HOME/.orcad-data\" ORCA_SANDBOX_ID=\"$ORCA_SANDBOX_ID\" \"${managed_env[@]}\" \\\n  NODE_COMPILE_CACHE=\"$ORCA_HOME/compile-cache\" ORCA_ORCAD_STARTUP_QUALIFICATION_DIR=\"$ORCA_HOME/startup-qualification\" \\\n  ORCA_SESSION_ENV_NAMES=\"${secret_names[*]}\" \"${agent_env[@]}\" \\\n  setsid nohup \"$node\" \"$ORCA_HOME/runtime/orcad/orcad-server.js\" \\\n  --port 6768 --bind 0.0.0.0 --pairing-address \"$ORCA_PUBLIC_WSS\" \\\n  --recipe-json --project-root \"$PROJECT\" \\\n  >\"$STATE/ready.json\" 2>\"$STATE/orcad.log\" </dev/null 9>&- &\necho $! >\"$STATE/orcad.pid\"\n\n# sshd for `orca ssh` (loopback only). Best effort: a workspace without it still serves orcad.\n\"$ORCA_HOME/bin/orca-sshd\" >/dev/null 2>\"$STATE/sshd-start.err\" || true\n\nfor _ in $(seq 1 1200); do\n  if grep -q '\"pairingCode\"' \"$STATE/ready.json\" 2>/dev/null; then\n    if [ -n \"$clone_pid\" ] && ! wait \"$clone_pid\"; then\n      echo 'repository clone failed' >&2\n      tail -n 5 \"$STATE/clone.log\" | redact_log >&2\n      exit 1\n    fi\n    register_project\n    print_ready\n    exit 0\n  fi\n  if ! kill -0 \"$(cat \"$STATE/orcad.pid\")\" 2>/dev/null; then\n    echo 'orcad exited before ready' >&2\n    tail -n 40 \"$STATE/orcad.log\" | redact_log >&2\n    exit 1\n  fi\n  sleep 0.05\ndone\necho 'orcad start timed out' >&2\nexit 1\n","orca-sandbox-drain":"#!/usr/bin/env bash\n# Asks orcad to quit before the VM stops: its shutdown turns working agent chats into durable\n# restart offers and flushes terminal restore hints, which the desktop continues after resume.\nset -euo pipefail\nSTATE=\"$HOME/.orca-sandbox\"\nWAIT_SECONDS=\"${1:-280}\"\npid=\"$(cat \"$STATE/orcad.pid\" 2>/dev/null || true)\"\nif [ -z \"$pid\" ] || ! kill -0 \"$pid\" 2>/dev/null; then\n  exit 0\nfi\nkill -TERM \"$pid\"\nfor _ in $(seq 1 $((WAIT_SECONDS * 10))); do\n  if ! kill -0 \"$pid\" 2>/dev/null; then\n    rm -f \"$STATE/orcad.pid\" \"$STATE/ready.json\"\n    exit 0\n  fi\n  sleep 0.1\ndone\n# Leave it running: the provider stop ends it, and the drain already had its window.\necho 'orcad still draining at deadline' >&2\nexit 0\n","orca-sandbox-env":"#!/usr/bin/env bash\n# Writes this session's secret env where new shells and agent launches read it (orca-session-env.sh).\n# Input: ORCA_SECRET_ENV (`NAME=<base64>` lines) from the control plane, at boot (orca-sandbox-start)\n# and whenever a secret changes (POST /v1/sandboxes/:id/env/refresh). The file lives on tmpfs only:\n# never on the sandbox disk, so the stop snapshot never carries it. Prints {\"names\":N} on success.\n# Also keeps Codex pointed at a configured OpenAI-compatible provider (OPENAI_BASE_URL), since Codex\n# does not read that variable: a managed block in ~/.codex/config.toml naming only the env var.\nset -euo pipefail\numask 077\nHOME=\"${HOME:-$(getent passwd \"$(id -u)\" | cut -d: -f6)}\"\ndir=\"/dev/shm/orca-env-$(id -u)\"\nif [ \"$(stat -f -c %T /dev/shm 2>/dev/null || true)\" != tmpfs ]; then\n  # No memory-only place to keep it: refuse rather than write secrets to disk.\n  echo 'no tmpfs for the session env' >&2\n  exit 3\nfi\nmkdir -p \"$dir\"\nchmod 700 \"$dir\"\n# Writes are ordered by the control plane's resolve time: an older refresh that lost a race is dropped.\ngeneration=\"${ORCA_ENV_GENERATION:-0}\"\ncase \"$generation\" in '' | *[!0-9]*) generation=0 ;; esac\ncurrent=\"$(cat \"$dir/generation\" 2>/dev/null || echo 0)\"\ncase \"$current\" in '' | *[!0-9]*) current=0 ;; esac\nif [ \"$generation\" -lt \"$current\" ]; then\n  printf '{\"stale\":true}\\n'\n  exit 0\nfi\ntmp=\"$(mktemp \"$dir/.session.env.XXXXXX\")\"\ncount=0\nopenai_base_url=''\nopenai_model=''\nanthropic_key_tail=''\nwhile IFS= read -r line; do\n  name=\"${line%%=*}\" b64=\"${line#*=}\"\n  case \"$name\" in '' | *[!A-Z0-9_]* | [0-9]* | ORCA_* | PATH | HOME | LD_* | DYLD_*) continue ;; esac\n  # Values stay base64 in the file; the shell hook decodes them.\n  printf '%s=%s\\n' \"$name\" \"$b64\" >>\"$tmp\"\n  count=$((count + 1))\n  case \"$name\" in\n    OPENAI_BASE_URL) openai_base_url=\"$(printf '%s' \"$b64\" | base64 -d)\" ;;\n    OPENAI_MODEL) openai_model=\"$(printf '%s' \"$b64\" | base64 -d)\" ;;\n    # Claude Code asks once per key whether to use ANTHROPIC_API_KEY; it remembers the last 20 chars.\n    ANTHROPIC_API_KEY) anthropic_key_tail=\"$(printf '%s' \"$b64\" | base64 -d | tail -c 20)\" ;;\n  esac\ndone < <(printf '%s\\n' \"${ORCA_SECRET_ENV:-}\")\nmv -f \"$tmp\" \"$dir/session.env\"\nprintf '%s' \"$generation\" >\"$dir/generation\"\n\n# ---- Codex: trust the workspace and use the configured provider (no secret values) ----\nPROJECT=/vercel/sandbox/project\ncodex_config=\"$HOME/.codex/config.toml\"\ntoml_string() { # TOML basic string; the control plane only accepts https URLs and plain model ids\n  local value=\"${1//\\\\/\\\\\\\\}\"\n  printf '\"%s\"' \"${value//\\\"/\\\\\\\"}\"\n}\nstrip_managed() { # drop both managed blocks\n  awk '/^# >>> orca-cloud managed/{skip=1} !skip{print} /^# <<< orca-cloud managed/{skip=0}' \"$1\"\n}\n# Always managed: an agent launched from the phone or the API has no one to answer Codex's\n# \"trust this folder?\" screen, so the workspace project is trusted up front.\nif true; then\n  mkdir -p \"$HOME/.codex\"\n  user_part=\"$(mktemp \"$HOME/.codex/.config.XXXXXX\")\"\n  if [ -f \"$codex_config\" ]; then strip_managed \"$codex_config\" >\"$user_part\"; fi\n  next=\"$(mktemp \"$HOME/.codex/.config.XXXXXX\")\"\n  openai_host=\"${openai_base_url#https://}\"\n  openai_host=\"${openai_host%%/*}\"\n  custom_provider=''\n  if [ -n \"$openai_base_url\" ] && [ \"$openai_host\" != api.openai.com ]; then custom_provider=1; fi\n  # Top-level keys must precede every table; each is skipped when the user already set it.\n  head_keys=\"$(awk '/^\\[/{exit} {print}' \"$user_part\")\"\n  has_key() { grep -Eq \"^[[:space:]]*$1[[:space:]]*=\" <<<\"$head_keys\"; }\n  {\n    printf '# >>> orca-cloud managed (Orca Cloud; edit in Orca settings)\\n'\n    # The sandbox is the isolation boundary: Codex's own bwrap sandbox can't start in it (\"Unexpected\n    # capabilities\"), and a prompt delivered from the phone or the API has no one to approve commands.\n    has_key sandbox_mode || printf 'sandbox_mode = \"danger-full-access\"\\n'\n    has_key approval_policy || printf 'approval_policy = \"never\"\\n'\n    if [ -n \"$custom_provider\" ]; then\n      has_key model_provider || printf 'model_provider = \"orca_cloud\"\\n'\n      if [ -n \"$openai_model\" ] && ! has_key model; then\n        printf 'model = %s\\n' \"$(toml_string \"$openai_model\")\"\n      fi\n    fi\n    printf '# <<< orca-cloud managed\\n'\n    cat \"$user_part\"\n    if [ -n \"$custom_provider\" ]; then\n      printf '\\n# >>> orca-cloud managed provider\\n[model_providers.orca_cloud]\\nname = \"Orca Cloud\"\\n'\n      printf 'base_url = %s\\nenv_key = \"OPENAI_API_KEY\"\\nwire_api = \"responses\"\\n' \"$(toml_string \"$openai_base_url\")\"\n      printf '# <<< orca-cloud managed\\n'\n    fi\n  } >\"$next\"\n  if ! grep -qF \"[projects.\\\"$PROJECT\\\"]\" \"$user_part\"; then\n    printf '\\n# >>> orca-cloud managed trust\\n[projects.\"%s\"]\\ntrust_level = \"trusted\"\\n# <<< orca-cloud managed\\n' \"$PROJECT\" >>\"$next\"\n  fi\n  chmod 600 \"$next\"\n  mv -f \"$next\" \"$codex_config\"\n  rm -f \"$user_part\"\nfi\n# ---- Claude Code: first-run screens answered once (theme picker, folder trust, bypass-mode warning,\n# the \"use this API key?\" question). A prompt delivered from the phone or the API has no one to click\n# through them, and the agent would sit there doing nothing. Merges; never touches credentials.\nnode_bin=\"$(command -v node || find /opt/orca/runtime/runtimes -type f -name node 2>/dev/null | head -n 1)\"\nif [ -n \"$node_bin\" ]; then\n  ORCA_PROJECT=\"$PROJECT\" ORCA_KEY_TAIL=\"$anthropic_key_tail\" \"$node_bin\" -e '\nconst fs = require(\"fs\"), path = require(\"path\"), os = require(\"os\")\nconst home = os.homedir()\nconst readJson = (file) => { try { const v = JSON.parse(fs.readFileSync(file, \"utf8\")); return v && typeof v === \"object\" && !Array.isArray(v) ? v : {} } catch { return {} } }\nconst write = (file, value) => {\n  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 })\n  const tmp = `${file}.orca-${process.pid}`\n  fs.writeFileSync(tmp, JSON.stringify(value, null, 2) + \"\\n\", { mode: 0o600 })\n  fs.renameSync(tmp, file)\n}\nconst claudeFile = path.join(process.env.CLAUDE_CONFIG_DIR || home, \".claude.json\")\nconst c = readJson(claudeFile)\nconst before = JSON.stringify(c)\nc.hasCompletedOnboarding = true\nc.theme = c.theme || \"dark\"\nc.bypassPermissionsModeAccepted = true\nc.projects = c.projects && typeof c.projects === \"object\" ? c.projects : {}\nconst p = process.env.ORCA_PROJECT\nc.projects[p] = { ...(c.projects[p] || {}), hasTrustDialogAccepted: true, hasCompletedProjectOnboarding: true }\nconst tail = process.env.ORCA_KEY_TAIL\nif (tail) {\n  const r = c.customApiKeyResponses && typeof c.customApiKeyResponses === \"object\" ? c.customApiKeyResponses : {}\n  const approved = Array.isArray(r.approved) ? r.approved : []\n  const rejected = Array.isArray(r.rejected) ? r.rejected.filter((t) => t !== tail) : []\n  c.customApiKeyResponses = { ...r, approved: approved.includes(tail) ? approved : [...approved, tail], rejected }\n}\nif (JSON.stringify(c) !== before) write(claudeFile, c)\nconst settingsFile = path.join(home, \".claude\", \"settings.json\")\nconst s = readJson(settingsFile)\nif (s.skipDangerousModePermissionPrompt !== true) write(settingsFile, { ...s, skipDangerousModePermissionPrompt: true })\n' || echo 'agent first-run state not seeded' >&2\nfi\nprintf '{\"names\":%d}\\n' \"$count\"\n","orca-session-env.sh":"# Orca Cloud: sourced by every new bash/zsh (via /etc/profile.d) so terminals and agents started\n# after a secret edit get the current values with no restart. The file is written by\n# /opt/orca/bin/orca-sandbox-env on tmpfs; names it no longer lists are unset. Cloud secrets win\n# over same-named values already in the environment.\n__orca_env_file=\"/dev/shm/orca-env-$(id -u 2>/dev/null)/session.env\"\nif [ -r \"$__orca_env_file\" ]; then\n  # $(...) word-splits in both bash and zsh.\n  for __orca_n in $(printf '%s' \"${ORCA_SESSION_ENV_NAMES-}\"); do\n    unset \"$__orca_n\" 2>/dev/null || true\n  done\n  __orca_names=''\n  while IFS= read -r __orca_line || [ -n \"$__orca_line\" ]; do\n    __orca_n=\"${__orca_line%%=*}\"\n    case \"$__orca_n\" in '' | *[!A-Z0-9_]* | [0-9]* | ORCA_* | PATH | HOME | LD_* | DYLD_*) continue ;; esac\n    export \"$__orca_n=$(printf '%s' \"${__orca_line#*=}\" | base64 -d 2>/dev/null)\"\n    __orca_names=\"$__orca_names $__orca_n\"\n  done <\"$__orca_env_file\"\n  export ORCA_SESSION_ENV_NAMES=\"${__orca_names# }\"\nfi\n# Default branch of the cloud workspace repo, once its first-boot clone exists (computed once per shell tree).\nif [ -n \"${ORCA_WORKSPACE_PATH-}\" ] && [ -z \"${ORCA_DEFAULT_BRANCH-}\" ]; then\n  __orca_branch=\"$(git -C \"$ORCA_WORKSPACE_PATH\" symbolic-ref --quiet --short refs/remotes/origin/HEAD 2>/dev/null || true)\"\n  if [ -n \"$__orca_branch\" ]; then\n    export ORCA_DEFAULT_BRANCH=\"${__orca_branch#origin/}\" CONDUCTOR_DEFAULT_BRANCH=\"${__orca_branch#origin/}\"\n  fi\nfi\nunset __orca_env_file __orca_line __orca_n __orca_names __orca_branch\n","orca-egress-probe":"#!/usr/bin/env bash\n# Bounded Node fetch against each credential host. Vercel transform rules have made undici hang on\n# response bodies (no content-length / transfer-encoding); report it instead of letting agents hang.\n# Prints one JSON line: {\"host\":\"api.github.com\",\"status\":\"ok\"|\"egress_framing_hang\"|\"error\"}.\nset -euo pipefail\nnode=\"$(find /opt/orca/runtime/runtimes -type f -name node | head -n 1)\"\nfor host in \"$@\"; do\n  \"$node\" -e '\n    const host = process.argv[1]\n    const timer = setTimeout(() => { console.log(JSON.stringify({ host, status: \"egress_framing_hang\" })); process.exit(0) }, 8000)\n    fetch(`https://${host}/`, { headers: { authorization: process.env.ORCA_PROBE_AUTHORIZATION ?? \"\" } })\n      .then((r) => r.arrayBuffer())\n      .then(() => { clearTimeout(timer); console.log(JSON.stringify({ host, status: \"ok\" })) })\n      .catch(() => { clearTimeout(timer); console.log(JSON.stringify({ host, status: \"error\" })) })\n  ' \"$host\"\ndone\n","orca-image-wipe":"#!/usr/bin/env bash\n# Runs last before the golden snapshot. Every sandbox cloned from the image must start without an\n# orcad identity, device registry, agent sign-in or shell history (clone-safe identity, risk #1).\nset -euo pipefail\npkill -f orcad-server.js 2>/dev/null || true\nfor path in \\\n  \"$HOME/.orcad-data\" \"$HOME/.orca-sandbox\" \"$HOME/.orca-desktop\" \"$HOME/.config/orca\" \"$HOME/.config/orca-dev\" \\\n  \"$HOME/.claude\" \"$HOME/.claude.json\" \"$HOME/.codex\" \"$HOME/.config/gh\" \"$HOME/.gemini\" \\\n  \"$HOME/.local/share/opencode\" \"$HOME/.npm\" \"$HOME/.cache\" \"$HOME/.config/google-chrome\" \"$HOME/.bash_history\" \\\n  /vercel/sandbox/project; do\n  rm -rf -- \"$path\"\ndone\nsudo rm -rf /tmp/* /var/tmp/* 2>/dev/null || true\nfor leftover in \"$HOME/.orcad-data\" \"$HOME/.claude\" \"$HOME/.codex\" \"$HOME/.config/gh\"; do\n  if [ -e \"$leftover\" ]; then\n    echo \"identity survived wipe: $leftover\" >&2\n    exit 1\n  fi\ndone\necho '{\"wiped\":true}'\n","orca-share-proxy":"#!/usr/bin/env node\n// Share-link proxy for this VM. Listens on 0.0.0.0:6769 (its public *.vercel.run route) and only\n// serves requests the control plane's share gateway signed with this session's key:\n//   x-orca-share: v2.<port>.<expiresAt>.<until>.<linkId>.<base64url HMAC-SHA256(key, everything before)>\n// A request must start before `expiresAt` (60s windows); its response or WebSocket is closed at\n// `until` (the link's expiry, at most 30 minutes out), so a revoked or expired link also loses open\n// streams. Signed requests are reverse-proxied to 127.0.0.1:<port>: streaming both ways, no\n// buffering, WebSocket upgrades piped raw. Anything unsigned gets a bare 404.\n// The key arrives on stdin (orca-sandbox-start pipes it), so it is never in this process's\n// environment or argv; ORCA_SHARE_PROXY_KEY in the env is accepted for tests. Optional\n// ORCA_SHARE_PROXY_PORT (default 6769). Plain Node, no dependencies.\n// getBuiltinModule (Node >= 22.3) works whether node loads this extensionless file as CommonJS\n// (in the VM) or as an ES module (under this repo's type:module package, in tests).\nconst crypto = process.getBuiltinModule('node:crypto')\nconst fs = process.getBuiltinModule('node:fs')\nconst http = process.getBuiltinModule('node:http')\nconst net = process.getBuiltinModule('node:net')\n\nconst LISTEN_PORT = Number(process.env.ORCA_SHARE_PROXY_PORT || 6769)\nconst KEY = Buffer.from((process.env.ORCA_SHARE_PROXY_KEY || fs.readFileSync(0, 'utf8')).trim(), 'base64url')\ndelete process.env.ORCA_SHARE_PROXY_KEY\n// Never proxy to the VM's sshd, orcad or this proxy itself.\n// 6080: the remote desktop (VNC behind a password) is for its owner's forward only.\nconst BLOCKED_PORTS = new Set([2222, 6080, 6768, LISTEN_PORT])\nconst MAX_SKEW_SECONDS = 300\nconst MAX_CONNECTION_SECONDS = 3600\nconst HOP_BY_HOP = ['connection', 'keep-alive', 'proxy-connection', 'transfer-encoding', 'te', 'trailer', 'upgrade']\n\nif (KEY.length < 32) {\n  console.error('orca-share-proxy: share proxy key missing or short')\n  process.exit(2)\n}\n\n/** The target port and close-by time (ms) for a validly signed request, else null. */\nfunction verify(header, nowMs) {\n  if (typeof header !== 'string') {\n    return null\n  }\n  const match = /^v2\\.(\\d{1,5})\\.(\\d{1,12})\\.(\\d{1,12})\\.([0-9a-f]{32})\\.([A-Za-z0-9_-]{43})$/.exec(header)\n  if (!match) {\n    return null\n  }\n  const now = Math.floor(nowMs / 1000)\n  const port = Number(match[1])\n  const expiresAt = Number(match[2])\n  const until = Number(match[3])\n  if (port < 1 || port > 65535 || BLOCKED_PORTS.has(port)) {\n    return null\n  }\n  if (expiresAt < now || expiresAt > now + MAX_SKEW_SECONDS || until <= now || until > now + MAX_CONNECTION_SECONDS) {\n    return null\n  }\n  const signed = header.slice(0, header.lastIndexOf('.'))\n  const expected = crypto.createHmac('sha256', KEY).update(signed).digest()\n  const given = Buffer.from(match[5], 'base64url')\n  return given.length === expected.length && crypto.timingSafeEqual(given, expected) ? { port, untilMs: until * 1000 } : null\n}\n\nfunction upstreamHeaders(raw, port) {\n  const headers = { ...raw }\n  const connectionTokens = String(raw.connection || '')\n    .split(',')\n    .map((token) => token.trim().toLowerCase())\n  for (const name of [...HOP_BY_HOP, ...connectionTokens, 'x-orca-share']) {\n    delete headers[name]\n  }\n  // Dev servers (Vite, Next) allow localhost hosts by default; the public host rides x-forwarded-host.\n  headers.host = `localhost:${port}`\n  return headers\n}\n\nfunction refuse(res) {\n  res.writeHead(404, { 'content-type': 'text/plain', 'cache-control': 'no-store' })\n  res.end('not found')\n}\n\n/** Ends `close` at the grant's deadline; the timer goes away with the connection. */\nfunction deadline(untilMs, close, ...emitters) {\n  const timer = setTimeout(close, Math.max(0, untilMs - Date.now()))\n  for (const emitter of emitters) {\n    emitter.once('close', () => clearTimeout(timer))\n  }\n}\n\nconst server = http.createServer((req, res) => {\n  const grant = verify(req.headers['x-orca-share'], Date.now())\n  if (grant === null) {\n    return refuse(res)\n  }\n  const { port } = grant\n  const upstream = http.request(\n    { host: '127.0.0.1', port, method: req.method, path: req.url, headers: upstreamHeaders(req.headers, port) },\n    (answer) => {\n      const headers = { ...answer.headers }\n      for (const name of HOP_BY_HOP) {\n        delete headers[name]\n      }\n      // Marks the answer as the app's, so the gateway can tell it from a route with no proxy behind it.\n      headers['x-orca-share-proxy'] = '1'\n      res.writeHead(answer.statusCode || 502, answer.statusMessage, headers)\n      answer.pipe(res)\n    }\n  )\n  deadline(grant.untilMs, () => {\n    upstream.destroy()\n    res.destroy()\n  }, res)\n  upstream.on('error', (error) => {\n    if (res.headersSent) {\n      res.destroy()\n      return\n    }\n    // The gateway renders its own page for this; the code tells it why. Status 200 on purpose: a 5xx\n    // from the VM reaches a Worker as Vercel's own 502 with our headers gone (found live).\n    res.writeHead(200, { 'content-type': 'text/plain', 'x-orca-share-proxy': '1', 'x-orca-share-error': error.code === 'ECONNREFUSED' ? 'no_listener' : 'upstream_failed' })\n    res.end('upstream unavailable')\n  })\n  req.on('aborted', () => upstream.destroy())\n  req.pipe(upstream)\n})\n\nserver.on('upgrade', (req, socket, head) => {\n  const grant = verify(req.headers['x-orca-share'], Date.now())\n  if (grant === null) {\n    socket.end('HTTP/1.1 404 Not Found\\r\\nconnection: close\\r\\ncontent-length: 0\\r\\n\\r\\n')\n    return\n  }\n  const { port } = grant\n  const headers = upstreamHeaders(req.headers, port)\n  const target = net.connect(port, '127.0.0.1', () => {\n    const lines = [`${req.method} ${req.url} HTTP/1.1`, `connection: upgrade`, `upgrade: ${req.headers.upgrade || 'websocket'}`]\n    for (const [name, value] of Object.entries(headers)) {\n      for (const item of Array.isArray(value) ? value : [value]) {\n        lines.push(`${name}: ${item}`)\n      }\n    }\n    target.write(`${lines.join('\\r\\n')}\\r\\n\\r\\n`)\n    if (head && head.length > 0) {\n      target.write(head)\n    }\n    socket.pipe(target)\n    target.pipe(socket)\n  })\n  const close = () => {\n    socket.destroy()\n    target.destroy()\n  }\n  deadline(grant.untilMs, close, socket)\n  target.on('error', () => {\n    if (socket.writable) {\n      socket.end('HTTP/1.1 200 OK\\r\\nx-orca-share-proxy: 1\\r\\nx-orca-share-error: no_listener\\r\\nconnection: close\\r\\ncontent-length: 0\\r\\n\\r\\n')\n    }\n    close()\n  })\n  socket.on('error', close)\n  target.on('close', () => socket.destroy())\n  socket.on('close', () => target.destroy())\n})\n\nserver.keepAliveTimeout = 65_000\nserver.headersTimeout = 70_000\n// No request timeout: previews can stream (SSE, long polls) until the grant's deadline.\nserver.requestTimeout = 0\nserver.listen(LISTEN_PORT, '0.0.0.0', () => {\n  console.log(`orca-share-proxy listening on ${LISTEN_PORT}`)\n})\n","orca-sshd":"#!/usr/bin/env bash\n# Starts this boot's unprivileged sshd on 127.0.0.1:2222 (idempotent). Nothing outside the VM can\n# reach that port: the desktop tunnels to it over orcad's runtime connection (`orca ssh-proxy`).\n# Key-only, single user (the sandbox user), no root. Its host key and authorized_keys live under\n# ~/.orca-sandbox/ssh on the persistent disk, so the host key stays the same across stop/resume;\n# orca-image-wipe removes that directory, so every VM cloned from the golden image makes its own.\n# Prints {\"port\":2222,\"user\":\"<user>\",\"hostKey\":\"ssh-ed25519 AAAA...\"} on success.\nset -euo pipefail\numask 077\nOPENSSH=/opt/orca/openssh\nSSH_DIR=\"$HOME/.orca-sandbox/ssh\"\nPORT=2222\nmkdir -p \"$SSH_DIR\"\nchmod 0700 \"$HOME/.orca-sandbox\" \"$SSH_DIR\"\nexec 8>\"$SSH_DIR/sshd.lock\"\nflock -w 30 8\n\nif [ ! -x \"$OPENSSH/sshd\" ]; then\n  echo 'sshd is not installed in this image' >&2\n  exit 3\nfi\nif [ ! -s \"$SSH_DIR/ssh_host_ed25519_key\" ]; then\n  rm -f \"$SSH_DIR/ssh_host_ed25519_key\" \"$SSH_DIR/ssh_host_ed25519_key.pub\"\n  ssh-keygen -q -t ed25519 -N '' -C \"orca-cloud-host\" -f \"$SSH_DIR/ssh_host_ed25519_key\"\nfi\ntouch \"$SSH_DIR/authorized_keys\"\nchmod 0600 \"$SSH_DIR/authorized_keys\"\n\n# Rewritten every start so an image update's settings apply to existing workspaces. PAM stays at\n# its compiled-in default (off): an unprivileged sshd cannot use it, and this build warns on `no`.\ncat >\"$SSH_DIR/sshd_config\" <<EOF\nListenAddress 127.0.0.1:$PORT\nHostKey $SSH_DIR/ssh_host_ed25519_key\nPidFile $SSH_DIR/sshd.pid\nAuthorizedKeysFile $SSH_DIR/authorized_keys\nSshdSessionPath $OPENSSH/sshd-session\n$([ -x \"$OPENSSH/sshd-auth\" ] && echo \"SshdAuthPath $OPENSSH/sshd-auth\")\nAllowUsers $(id -un)\nPermitRootLogin no\nPubkeyAuthentication yes\nPasswordAuthentication no\nKbdInteractiveAuthentication no\nHostbasedAuthentication no\nStrictModes yes\nAllowTcpForwarding local\nAllowAgentForwarding no\nAllowStreamLocalForwarding local\nGatewayPorts no\nX11Forwarding no\nPermitTunnel no\nPermitUserEnvironment no\nClientAliveInterval 30\nClientAliveCountMax 4\nMaxStartups 10:30:60\nSubsystem sftp $OPENSSH/sftp-server\nEOF\n\npid=\"$(cat \"$SSH_DIR/sshd.pid\" 2>/dev/null || echo 0)\"\n# Resume reboots from disk, so a recorded pid can name a dead process or an unrelated one.\nif ! { kill -0 \"$pid\" 2>/dev/null && grep -q sshd \"/proc/$pid/cmdline\" 2>/dev/null; }; then\n  rm -f \"$SSH_DIR/sshd.pid\"\n  : >\"$SSH_DIR/sshd.log\"\n  \"$OPENSSH/sshd\" -t -f \"$SSH_DIR/sshd_config\"\n  \"$OPENSSH/sshd\" -f \"$SSH_DIR/sshd_config\" -E \"$SSH_DIR/sshd.log\"\n  for _ in $(seq 1 100); do\n    [ -s \"$SSH_DIR/sshd.pid\" ] && break\n    sleep 0.02\n  done\n  [ -s \"$SSH_DIR/sshd.pid\" ] || { echo 'sshd did not start' >&2; tail -n 20 \"$SSH_DIR/sshd.log\" >&2; exit 1; }\nfi\n\nhost_key=\"$(cut -d' ' -f1-2 \"$SSH_DIR/ssh_host_ed25519_key.pub\")\"\nprintf '{\"port\":%s,\"user\":\"%s\",\"hostKey\":\"%s\"}\\n' \"$PORT\" \"$(id -un)\" \"$host_key\"\n","orca-ssh-keys":"#!/usr/bin/env bash\n# `orca-ssh-keys add|remove`: adds or removes one desktop's key in the Orca-managed authorized_keys\n# of this VM's sshd, then makes sure sshd runs. The control plane passes the key in\n# ORCA_SSH_PUBLIC_KEY (`ssh-ed25519 <base64> <comment>`), never on the command line. Keys are\n# matched by their base64 blob, so a renamed comment cannot keep a revoked key alive.\n# Prints orca-sshd's {\"port\":...,\"user\":...,\"hostKey\":...} line on success.\nset -euo pipefail\numask 077\nSSH_DIR=\"$HOME/.orca-sandbox/ssh\"\naction=\"${1:-}\"\nkey=\"${ORCA_SSH_PUBLIC_KEY:-}\"\n# grep matches per line: a second line could carry key options past the check below.\ncase \"$key\" in *$'\\n'* | *$'\\r'*) echo 'invalid public key' >&2; exit 2 ;; esac\n# One line, ed25519 only, a plain comment: nothing that sshd would read as key options.\nif ! printf '%s' \"$key\" | grep -Eq '^ssh-ed25519 [A-Za-z0-9+/]{68} [A-Za-z0-9@._:+-]{1,200}$'; then\n  echo 'invalid public key' >&2\n  exit 2\nfi\nblob=\"$(printf '%s' \"$key\" | cut -d' ' -f2)\"\nmkdir -p \"$SSH_DIR\"\nchmod 0700 \"$HOME/.orca-sandbox\" \"$SSH_DIR\"\nexec 7>\"$SSH_DIR/keys.lock\"\nflock -w 30 7\ntouch \"$SSH_DIR/authorized_keys\"\nnext=\"$(mktemp \"$SSH_DIR/authorized_keys.XXXXXX\")\"\n# Drop the key wherever it appears (with or without options), then append it on add.\nawk -v blob=\"$blob\" '{ for (i = 1; i <= NF; i++) if ($i == blob) next; print }' \\\n  \"$SSH_DIR/authorized_keys\" >\"$next\"\ncase \"$action\" in\n  add) printf '%s\\n' \"$key\" >>\"$next\" ;;\n  remove) ;;\n  *) rm -f \"$next\"; echo 'usage: orca-ssh-keys add|remove' >&2; exit 2 ;;\nesac\nchmod 0600 \"$next\"\nmv -f \"$next\" \"$SSH_DIR/authorized_keys\"\nexec /opt/orca/bin/orca-sshd\n","orca-desktop-start":"#!/usr/bin/env bash\n# Starts the on-demand remote desktop (idempotent) and mints one connection ticket. Prints one line:\n# {\"schemaVersion\":2,\"port\":6080,\"display\":\":1\",\"path\":\"vnc.html\",\"ticket\":\"<43 chars>\",\"expiresInMs\":60000}\n# Xvnc (X server + VNC in one) listens on a 0600 unix socket only, with no VNC auth: only this uid\n# can open it. orca-desktop-proxy (websockify + a ticket gate) serves noVNC on 127.0.0.1 and\n# bridges WebSockets to that socket. Nothing is reachable from outside the VM: the desktop app\n# reaches it through Orca's port forward, a localhost port on the user's computer that any local\n# process or web page can reach, so each WebSocket needs a ticket from here: 32 random bytes,\n# single use, valid for 60 s, stored only as its sha256 (the file name; its content is the expiry).\n# The ticket goes to stdout only (the control plane hands it to the desktop app). Never started at boot.\nset -euo pipefail\numask 077\nDESKTOP=/opt/orca/desktop\nSTATE=\"$HOME/.orca-desktop\"\nPORT=\"${ORCA_DESKTOP_PORT:-6080}\"\nDISPLAY_NUM=\"${ORCA_DESKTOP_DISPLAY:-1}\"\nGEOMETRY=\"${ORCA_DESKTOP_GEOMETRY:-1280x800}\"\nSOCKET=\"$STATE/vnc.sock\"\n# The parent's DISPLAY must not leak into the WM/xterm below; they use ours.\nexport DISPLAY=\":$DISPLAY_NUM\"\n\n# Exit 3 = this image has no desktop (built before it, or its optional install failed).\nfail() { printf 'orca-desktop: %s\\n' \"$1\" >&2; exit \"${2:-1}\"; }\ncase \"$PORT\" in '' | *[!0-9]*) fail 'ORCA_DESKTOP_PORT must be a number' ;; esac\ncase \"$DISPLAY_NUM\" in '' | *[!0-9]*) fail 'ORCA_DESKTOP_DISPLAY must be a number' ;; esac\ncase \"$GEOMETRY\" in [0-9]*x[0-9]*) ;; *) fail 'ORCA_DESKTOP_GEOMETRY must look like 1280x800' ;; esac\ncommand -v Xvnc >/dev/null || fail 'not installed in this image (Xvnc missing)' 3\n[ -s \"$DESKTOP/novnc/vnc.html\" ] || fail 'not installed in this image (noVNC missing)' 3\nPROXY=\"$(dirname \"$(readlink -f \"$0\")\")/orca-desktop-proxy\"\n[ -x \"$PROXY\" ] || fail 'orca-desktop-proxy missing next to this script'\nTICKETS=\"$STATE/tickets\"\nTICKET_TTL_S=60\n# Xvnc's mode: a previous version of this script ran it with VncAuth; restart it in this mode.\nMODE=ticket-v1\n\nmkdir -p \"$STATE\"\nexec 9>\"$STATE/start.lock\"\nflock -w 30 9 || fail 'another start is in progress'\n\npid_of() { # never \"0\": kill 0 targets our own process group\n  local pid\n  pid=\"$(cat \"$STATE/$1.pid\" 2>/dev/null || true)\"\n  case \"$pid\" in '' | 0 | *[!0-9]*) return 1 ;; esac\n  printf '%s' \"$pid\"\n}\nalive() { local pid; pid=\"$(pid_of \"$1\")\" && kill -0 \"$pid\" 2>/dev/null; }\nmint_ticket() { # prints the ticket; stores only its sha256, with the expiry as content\n  local ticket now digest\n  mkdir -p \"$TICKETS\"\n  now=\"$(date +%s)\"\n  # Expired or spent-but-unswept tickets; keep at most 16 live ones (oldest go first).\n  for file in \"$TICKETS\"/*; do\n    [ -f \"$file\" ] || continue\n    [ \"$(cat \"$file\" 2>/dev/null || echo 0)\" -ge \"$now\" ] 2>/dev/null || rm -f \"$file\"\n  done\n  # shellcheck disable=SC2012 # names are hex digests\n  ls -1t \"$TICKETS\" 2>/dev/null | tail -n +16 | while read -r old; do rm -f \"$TICKETS/$old\"; done\n  ticket=\"$(head -c 32 /dev/urandom | base64 | tr '+/' '-_' | tr -d '=\\n')\"\n  [ \"${#ticket}\" = 43 ] || fail 'could not generate a ticket'\n  digest=\"$(printf '%s' \"$ticket\" | sha256sum | cut -d' ' -f1)\"\n  printf '%s' \"$((now + TICKET_TTL_S))\" >\"$TICKETS/.$digest\" && mv \"$TICKETS/.$digest\" \"$TICKETS/$digest\"\n  printf '%s' \"$ticket\"\n}\nready_line() {\n  local ticket\n  ticket=\"$(mint_ticket)\" || exit 1\n  printf '{\"schemaVersion\":2,\"port\":%s,\"display\":\":%s\",\"path\":\"vnc.html\",\"ticket\":\"%s\",\"expiresInMs\":%s}\\n' \\\n    \"$PORT\" \"$DISPLAY_NUM\" \"$ticket\" \"$((TICKET_TTL_S * 1000))\"\n}\nlistening() { # the proxy answers HTTP on loopback\n  curl -fsS -o /dev/null --max-time 1 \"http://127.0.0.1:$PORT/vnc.html\" 2>/dev/null\n}\n\n# Pids from a previous boot (resume = reboot from disk) name dead or unrelated processes.\nboot_id=\"$(cat /proc/sys/kernel/random/boot_id)\"\nif [ \"$(cat \"$STATE/boot-id\" 2>/dev/null || true)\" != \"$boot_id\" ]; then\n  rm -rf \"$STATE\"/*.pid \"$SOCKET\" \"$STATE/password\" \"$STATE/passwd\" \"$STATE/mode\" \"$TICKETS\"\n  printf '%s' \"$boot_id\" >\"$STATE/boot-id\"\nfi\n\n# Same boot, older script: its websockify had no ticket gate and its Xvnc wanted a VNC password.\nrm -f \"$STATE/password\" \"$STATE/passwd\"\nif alive websockify; then kill \"$(pid_of websockify)\" 2>/dev/null || true; fi\nrm -f \"$STATE/websockify.pid\"\ncurrent_mode() { cat \"$STATE/mode\" 2>/dev/null || true; }\n\nif alive xvnc && alive proxy && listening && [ \"$(current_mode)\" = \"$MODE\" ]; then\n  ready_line\n  exit 0\nfi\n\nstart() { # name cmd... — detached, logs in $STATE/<name>.log\n  local name=$1; shift\n  # 9>&-: children must not inherit the start lock, or the next call waits for them to exit.\n  setsid nohup \"$@\" >\"$STATE/$name.log\" 2>&1 </dev/null 9>&- &\n  echo $! >\"$STATE/$name.pid\"\n}\n\nif ! alive xvnc || [ \"$(current_mode)\" != \"$MODE\" ]; then\n  if alive xvnc; then kill \"$(pid_of xvnc)\" 2>/dev/null || true; sleep 0.2; fi\n  rm -f \"$SOCKET\"\n  # -rfbport -1: no TCP VNC port at all, only a 0600 unix socket (in the 0700 state dir) for the\n  # proxy. SecurityTypes None is safe only because of that: the ticket gate is in the proxy.\n  # SendPrimary=0: only explicit copies (xterm copies its selection, below) leave the sandbox.\n  # The X display itself takes a cookie from ~/.Xauthority (Xlib's default for this user), so only\n  # this uid's processes (agents, apps they start on DISPLAY=:1) can open it.\n  auth=()\n  if command -v xauth >/dev/null && command -v mcookie >/dev/null; then\n    xauth -q -f \"$HOME/.Xauthority\" add \":$DISPLAY_NUM\" . \"$(mcookie)\" 9>&- && auth=(-auth \"$HOME/.Xauthority\")\n  fi\n  start xvnc Xvnc \":$DISPLAY_NUM\" \"${auth[@]}\" -geometry \"$GEOMETRY\" -depth 24 -nolisten tcp \\\n    -rfbport -1 -rfbunixpath \"$SOCKET\" -rfbunixmode 0600 \\\n    -SecurityTypes None -SendPrimary=0 \\\n    -AlwaysShared -AcceptSetDesktopSize -desktop 'Remote desktop'\n  printf '%s' \"$MODE\" >\"$STATE/mode\"\n  for _ in $(seq 1 100); do\n    [ -S \"$SOCKET\" ] && break\n    alive xvnc || { tail -n 20 \"$STATE/xvnc.log\" >&2; fail 'Xvnc exited'; }\n    sleep 0.05\n  done\n  [ -S \"$SOCKET\" ] || fail 'Xvnc did not create its socket'\n  if command -v xsetroot >/dev/null; then xsetroot -solid '#1e1f22' 9>&- || true; fi\n  if command -v openbox >/dev/null; then\n    # Dark, flat theme to match Orca; the first terminal stays maximized as the tab resizes the screen.\n    printf '%s\\n' '<?xml version=\"1.0\"?>' \\\n      '<openbox_config xmlns=\"http://openbox.org/3.4/rc\"><theme><name>Onyx</name></theme>' \\\n      '<applications><application class=\"XTerm\"><maximized>yes</maximized></application></applications>' \\\n      '</openbox_config>' >\"$STATE/openbox.xml\"\n    start wm openbox --config-file \"$STATE/openbox.xml\"\n    # Let it manage the screen before the terminal maps, so its maximize rule applies.\n    sleep 0.2\n  elif command -v twm >/dev/null; then\n    start wm twm\n  fi\n  if command -v xterm >/dev/null; then\n    # selectToClipboard: a selection is a copy (to CLIPBOARD, which reaches this computer).\n    start xterm xterm -maximized -bg '#1e1f22' -fg '#d4d4d4' -fa 'Liberation Mono,Monospace' -fs 11 \\\n      -xrm 'XTerm*selectToClipboard: true'\n  fi\nfi\n\nif ! alive proxy || ! listening; then\n  if alive proxy; then kill \"$(pid_of proxy)\" 2>/dev/null || true; sleep 0.1; fi\n  mkdir -p \"$TICKETS\"\n  PYTHONPATH=\"$DESKTOP/websockify\" start proxy python3 -P -W ignore::UserWarning \"$PROXY\" \\\n    --listen \"$PORT\" --web \"$DESKTOP/novnc\" --unix-target \"$SOCKET\" --tickets \"$TICKETS\"\n  for _ in $(seq 1 100); do\n    listening && break\n    alive proxy || { tail -n 20 \"$STATE/proxy.log\" >&2; fail 'orca-desktop-proxy exited'; }\n    sleep 0.05\n  done\n  listening || fail \"orca-desktop-proxy is not answering on 127.0.0.1:$PORT\"\nfi\nready_line\n","orca-desktop-proxy":"#!/usr/bin/env python3\n# Remote desktop gateway, started by orca-desktop-start: serves noVNC on 127.0.0.1 and bridges one\n# WebSocket per single-use ticket to Xvnc's 0600 unix socket (Xvnc itself has no VNC auth: only this\n# uid can open the socket). The port is reached only through Orca's localhost forward on the user's\n# computer, where any local process or web page could knock, so every WebSocket must carry an\n# unused, unexpired ticket minted by orca-desktop-start (see consume_ticket), from a page on the same\n# localhost origin. Tickets never reach a log: paths are scrubbed before websockify logs them.\n#   orca-desktop-proxy --listen PORT --web DIR --unix-target SOCKET --tickets DIR\n# stdlib + websockify (pinned tarball in /opt/orca/desktop/websockify, on PYTHONPATH) only.\nimport argparse\nimport hashlib\nimport hmac\nimport logging\nimport os\nimport re\nimport sys\nimport time\nfrom urllib.parse import parse_qs, urlsplit\n\nfrom websockify import websocketproxy\n\nTICKET_RE = re.compile(r'^[A-Za-z0-9_-]{43}$')  # 32 random bytes, base64url without padding\nSCRUB_RE = re.compile(r'([?&]ticket=)[^&\\s\\'\"]*')\nLOOPBACK_HOST_RE = re.compile(r'^(localhost|127\\.0\\.0\\.1|\\[::1\\])(:[0-9]{1,5})?$')\nWS_PATH = '/websockify'\nPAGE_SCRIPT = os.path.join(os.path.dirname(os.path.realpath(__file__)), 'orca-desktop-page.js')\n# The page may only talk to its own origin (its WebSocket included): even a URL that tries to point\n# noVNC elsewhere cannot carry a ticket or the user's keys off this forward.\nPAGE_CSP = \"connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'self'\"\nPAGE_TAG = b'<script type=\"module\" src=\"orca-desktop-page.js\"></script>\\n</head>'\n\n\ndef scrub(text):\n    return SCRUB_RE.sub(r'\\1<redacted>', str(text))\n\n\ndef ticket_digest(ticket):\n    return hashlib.sha256(ticket.encode('ascii')).hexdigest()\n\n\ndef consume_ticket(directory, ticket, now=None):\n    \"\"\"True once per minted ticket, within its lifetime. The ticket file (named by the ticket's\n    sha256, holding its expiry) is unlinked on first use, so a replay or a racing second\n    connection finds nothing; each request runs in its own forked process, so state is on disk.\"\"\"\n    if not isinstance(ticket, str) or not TICKET_RE.match(ticket):\n        return False\n    digest = ticket_digest(ticket)\n    match = None\n    try:\n        names = os.listdir(directory)\n    except OSError:\n        return False\n    for name in names:\n        # Compare every entry in constant time; never short-circuit on a prefix.\n        if hmac.compare_digest(name.encode('ascii', 'replace'), digest.encode('ascii')):\n            match = name\n    if match is None:\n        return False\n    path = os.path.join(directory, match)\n    try:\n        with open(path, 'r', encoding='ascii') as handle:\n            expires_at = int(handle.read().strip() or '0')\n    except (OSError, ValueError):\n        expires_at = 0\n    try:\n        os.unlink(path)  # the consume: only one caller can win this\n    except FileNotFoundError:\n        return False\n    return (now if now is not None else time.time()) <= expires_at\n\n\ndef same_loopback_origin(headers):\n    \"\"\"The page and the WebSocket share one localhost origin (blocks other local sites and DNS\n    rebinding). The port is the user's local forward, which may differ from ours, so compare the\n    Origin with the Host the browser dialed rather than with a fixed port.\"\"\"\n    host = (headers.get('Host') or '').strip().lower()\n    origin = (headers.get('Origin') or '').strip().lower()\n    return loopback_host(host) and origin == 'http://' + host\n\n\ndef loopback_host(host):\n    return bool(LOOPBACK_HOST_RE.match(host or ''))\n\n\nclass TicketedProxyHandler(websocketproxy.ProxyRequestHandler):\n    \"\"\"websockify's proxy handler plus the ticket + origin gate. Module level (not a closure) so\n    websockify's per-connection multiprocessing can pickle it under any start method.\"\"\"\n\n    def log_message(self, format, *args):  # noqa: A002 (websockify's signature)\n        super().log_message('%s', scrub(format % args if args else format))\n\n    def reject(self, code, reason):\n        self.send_response(code)\n        self.send_header('Content-Length', '0')\n        self.send_header('Connection', 'close')\n        self.end_headers()\n        self.close_connection = True\n        raise self.server.EClose('desktop: websocket refused (%s)' % reason)\n\n    def validate_connection(self):\n        parts = urlsplit(self.path)\n        ticket = (parse_qs(parts.query).get('ticket') or [''])[0]\n        # Drop it before anything below (websockify's own logging included) can see self.path.\n        self.path = parts.path\n        if parts.path != WS_PATH:\n            self.reject(404, 'path')\n        if not same_loopback_origin(self.headers):\n            self.reject(403, 'origin')\n        if not consume_ticket(self.server.orca_tickets_dir, ticket):\n            self.reject(403, 'ticket')\n\n    def loopback_request(self):\n        if loopback_host((self.headers.get('Host') or '').strip().lower()):\n            return True\n        self.send_error(403)\n        return False\n\n    def do_GET(self):\n        if not self.loopback_request():\n            return None\n        path = urlsplit(self.path).path\n        if path == '/orca-desktop-page.js':\n            return self.send_bytes(read_file(PAGE_SCRIPT), 'text/javascript; charset=utf-8')\n        if path == '/vnc.html':\n            page = read_file(os.path.join(self.server.web, 'vnc.html'))\n            return self.send_bytes(page.replace(b'</head>', PAGE_TAG, 1), 'text/html; charset=utf-8', PAGE_CSP)\n        return super().do_GET()\n\n    def do_HEAD(self):\n        if not self.loopback_request():\n            return None\n        return super().do_HEAD()\n\n    def send_bytes(self, body, content_type, csp=None):\n        self.send_response(200)\n        self.send_header('Content-Type', content_type)\n        if csp:\n            self.send_header('Content-Security-Policy', csp)\n        self.send_header('Content-Length', str(len(body)))\n        self.send_header('Cache-Control', 'no-store')\n        self.send_header('Referrer-Policy', 'no-referrer')\n        self.end_headers()\n        self.wfile.write(body)\n        return None\n\n\ndef read_file(path):\n    with open(path, 'rb') as handle:\n        return handle.read()\n\n\ndef main(argv):\n    parser = argparse.ArgumentParser()\n    parser.add_argument('--listen', type=int, required=True)\n    parser.add_argument('--web', required=True)\n    parser.add_argument('--unix-target', required=True)\n    parser.add_argument('--tickets', required=True)\n    args = parser.parse_args(argv)\n    logging.basicConfig(level=logging.INFO, format='%(message)s')\n    server = websocketproxy.WebSocketProxy(\n        RequestHandlerClass=TicketedProxyHandler,\n        listen_host='127.0.0.1',\n        listen_port=args.listen,\n        web=args.web,\n        file_only=True,\n        unix_target=args.unix_target,\n    )\n    server.orca_tickets_dir = os.path.abspath(args.tickets)\n    server.start_server()\n\n\nif __name__ == '__main__':\n    main(sys.argv[1:])\n","orca-desktop-page.js":"// Orca's glue for noVNC, injected into vnc.html by orca-desktop-proxy. Orca (the desktop app's\n// main process) drives it through window.orcaDesktop:\n// - tickets: the page never connects by itself. Each WebSocket needs a fresh single-use ticket,\n//   which Orca hands over with connect(ticket) after nextTicketRequest() resolves: 'ticket' on\n//   load or after a session dropped, 'retry' after an attempt that never connected. Tickets live\n//   only in memory here: never in the URL, storage or noVNC's settings.\n// - pause(message, label): Orca stopped retrying; show why, with a Reconnect button. resume()\n//   (Orca reopened the desktop) or the button asks for a ticket again.\n// - fit: resize=remote makes Xvnc follow the tab; a server without SetDesktopSize gets scaling.\n// - clipboard: a copy inside the desktop right after user input there goes to this computer's\n//   clipboard; paste(text, chord) sets the sandbox's clipboard first, then replays the paste key.\nimport UI from './app/ui.js';\nimport * as WebUtil from './app/webutil.js';\n\nconst WS_PATH = 'websockify';\nconst RESIZE_FALLBACK_MS = 1500;\n// A copy inside the desktop follows a copy key or a selection (drag or double-click) there; other\n// clipboard changes (an agent in the sandbox running xclip) must not overwrite this computer's\n// clipboard. Plain typing does not open the window.\nconst USER_COPY_WINDOW_MS = 1500;\nconst DRAG_PX = 4;\nconst MAX_CLIPBOARD_CHARS = 1 << 20;\nconst TICKET_RE = /^[A-Za-z0-9_-]{43}$/;\nconst XK = { v: 0x0076, V: 0x0056, Insert: 0xff63, Shift_L: 0xffe1, Super_L: 0xffeb, Super_R: 0xffec };\n\nlet state = 'idle'; // idle | connecting | connected | disconnected | paused\nlet attemptConnected = true;\nlet ticketWaiters = [];\nlet lastCopyIntent = 0;\nlet pointerStart = null;\n\nconst style = document.createElement('style');\n// Orca owns connecting and the chrome: noVNC's Connect button would only try without a ticket,\n// and its control bar duplicates what the Orca tab does (fit, clipboard, keyboard release).\n// The pause card follows Orca's theme: Orca sets Electron's theme source from its own setting, so\n// prefers-color-scheme here is Orca's light or dark, and it follows a switch while paused. The\n// page cannot read Orca's tokens, so these mirror them (popover, border, focus ring).\nstyle.textContent = `\n#noVNC_connect_dlg, #noVNC_control_bar_anchor { display: none !important; }\n#orca_pause { --orca-scrim: rgb(10 10 10 / 0.88); --orca-card: #171717; --orca-text: #f0f0f0;\n  --orca-border: rgb(255 255 255 / 0.1); --orca-control: rgb(255 255 255 / 0.25);\n  --orca-control-hover: rgb(255 255 255 / 0.08); --orca-focus: color-mix(in oklab, #f0f0f0 65%, #0a0a0a);\n  color-scheme: dark; position: fixed; inset: 0; display: none; align-items: center;\n  justify-content: center; padding: 16px; background: var(--orca-scrim); z-index: 1000;\n  font: 13px/1.5 system-ui, sans-serif; }\n@media (prefers-color-scheme: light) {\n  #orca_pause { --orca-scrim: rgb(255 255 255 / 0.88); --orca-card: #fff; --orca-text: #0a0a0a;\n    --orca-border: #e5e5e5; --orca-control: #a3a3a3; --orca-control-hover: #f5f5f5;\n    --orca-focus: color-mix(in oklab, #0a0a0a 55%, #fff); color-scheme: light; }\n}\n#orca_pause.open { display: flex; }\n#orca_pause > div { max-width: 360px; padding: 16px; border: 1px solid var(--orca-border);\n  border-radius: 8px; background: var(--orca-card); color: var(--orca-text); text-align: center;\n  box-shadow: 0 8px 24px rgb(0 0 0 / 0.16); }\n#orca_pause p { margin: 0; }\n#orca_pause button { margin-top: 12px; padding: 4px 12px; border: 1px solid var(--orca-control);\n  border-radius: 6px; background: transparent; color: var(--orca-text); font: inherit; cursor: pointer; }\n#orca_pause button:hover { background: var(--orca-control-hover); }\n#orca_pause button:focus-visible { outline: 2px solid var(--orca-focus); outline-offset: 2px; }\n@media (prefers-reduced-motion: no-preference) {\n  #orca_pause.open > div { animation: orca-pause-in 120ms ease-out; }\n}\n@keyframes orca-pause-in { from { opacity: 0; transform: translateY(4px); } }\n`;\ndocument.head.appendChild(style);\n\nconst overlay = document.createElement('div');\noverlay.id = 'orca_pause';\noverlay.innerHTML = '<div role=\"alert\"><p></p><button type=\"button\"></button></div>';\noverlay.querySelector('button').addEventListener('click', () => resume());\ndocument.addEventListener('DOMContentLoaded', () => document.body.appendChild(overlay));\n\nwindow.addEventListener('keydown', (event) => {\n  if ((event.ctrlKey || event.metaKey) && !event.altKey && (event.key === 'c' || event.key === 'C' || event.key === 'Insert')) {\n    lastCopyIntent = Date.now();\n  }\n}, true);\nwindow.addEventListener('pointerdown', (event) => {\n  pointerStart = { x: event.clientX, y: event.clientY };\n}, true);\n// A double- or triple-click selects a word or line (pointer events carry no click count).\nwindow.addEventListener('mousedown', (event) => {\n  if (event.detail >= 2) {\n    lastCopyIntent = Date.now();\n  }\n}, true);\nwindow.addEventListener('pointerup', (event) => {\n  if (pointerStart && Math.hypot(event.clientX - pointerStart.x, event.clientY - pointerStart.y) >= DRAG_PX) {\n    lastCopyIntent = Date.now();\n  }\n  pointerStart = null;\n}, true);\n\nfunction requestTicket() {\n  const answer = attemptConnected ? 'ticket' : 'retry';\n  const waiters = ticketWaiters;\n  ticketWaiters = [];\n  waiters.forEach((resolve) => resolve(answer));\n}\n\nasync function whenStarted() {\n  while (document.documentElement.classList.contains('noVNC_loading')) {\n    await new Promise((resolve) => setTimeout(resolve, 25));\n  }\n}\n\nfunction onConnect() {\n  state = 'connected';\n  attemptConnected = true;\n  UI.hideStatus();\n  setTimeout(() => {\n    // Xvnc answers SetDesktopSize; anything that does not gets scaled into the tab instead.\n    if (UI.rfb && state === 'connected' && !UI.rfb._supportsSetDesktopSize) {\n      UI.rfb.scaleViewport = true;\n    }\n  }, RESIZE_FALLBACK_MS);\n}\n\nfunction onDisconnect() {\n  if (state === 'paused') {\n    return;\n  }\n  state = 'disconnected';\n  // The ticket is spent: ask Orca for a new one (a dropped forward, a restart of the desktop).\n  requestTicket();\n}\n\nfunction onClipboard(event) {\n  const text = event.detail && event.detail.text;\n  if (typeof text !== 'string' || text.length > MAX_CLIPBOARD_CHARS) {\n    return;\n  }\n  if (Date.now() - lastCopyIntent > USER_COPY_WINDOW_MS || !document.hasFocus()) {\n    return;\n  }\n  navigator.clipboard.writeText(text).catch(() => {});\n}\n\nasync function connect(ticket) {\n  if (typeof ticket !== 'string' || !TICKET_RE.test(ticket)) {\n    return 'invalid';\n  }\n  if (state === 'connecting' || state === 'connected' || state === 'paused') {\n    return state;\n  }\n  await whenStarted();\n  if (UI.rfb) {\n    return 'connecting';\n  }\n  state = 'connecting';\n  attemptConnected = false;\n  // UI.connect reads the path setting synchronously and opens the WebSocket in RFB's constructor;\n  // the in-memory setting is restored right after, so the ticket is never kept or shown.\n  // Only ever this page's own origin: noVNC also reads host, port, encrypt, repeater and logging\n  // from the URL, which must never send a ticketed session (and the user's keys) elsewhere.\n  WebUtil.setSetting('host', '');\n  WebUtil.setSetting('port', '');\n  WebUtil.setSetting('encrypt', false);\n  WebUtil.setSetting('repeaterID', '');\n  WebUtil.setSetting('path', `${WS_PATH}?ticket=${ticket}`);\n  try {\n    UI.connect();\n  } finally {\n    WebUtil.setSetting('path', WS_PATH);\n  }\n  const rfb = UI.rfb;\n  if (!rfb) {\n    state = 'disconnected';\n    requestTicket();\n    return 'failed';\n  }\n  rfb.addEventListener('connect', onConnect);\n  rfb.addEventListener('disconnect', onDisconnect);\n  rfb.addEventListener('clipboard', onClipboard);\n  return 'connecting';\n}\n\n/** Pastes this computer's clipboard: the sandbox's clipboard first, then the paste key itself. */\nfunction paste(text, chord) {\n  const rfb = UI.rfb;\n  if (!rfb || state !== 'connected' || typeof text !== 'string' || text.length > MAX_CLIPBOARD_CHARS) {\n    return false;\n  }\n  rfb.clipboardPasteFrom(text);\n  if (chord && chord.kind === 'mac') {\n    // Cmd+V: Linux apps do not paste on Super+V, so release Super and send Shift+Insert.\n    rfb.sendKey(XK.Super_L, 'MetaLeft', false);\n    rfb.sendKey(XK.Super_R, 'MetaRight', false);\n    rfb.sendKey(XK.Shift_L, 'ShiftLeft', true);\n    rfb.sendKey(XK.Insert, 'Insert');\n    rfb.sendKey(XK.Shift_L, 'ShiftLeft', false);\n  } else if (chord && chord.kind === 'replay') {\n    // Ctrl+V, Ctrl+Shift+V, Shift+Insert: the held modifiers already reached the sandbox.\n    const insert = chord.key === 'Insert';\n    rfb.sendKey(insert ? XK.Insert : chord.key === 'V' ? XK.V : XK.v, insert ? 'Insert' : 'KeyV');\n  }\n  return true;\n}\n\nfunction pause(message, label, tone) {\n  state = 'paused';\n  if (UI.rfb) {\n    UI.rfb.disconnect();\n  }\n  UI.hideStatus();\n  overlay.querySelector('p').textContent = String(message || '');\n  overlay.querySelector('button').textContent = String(label || 'Reconnect');\n  // Asleep and starting are states, not errors: announce them politely.\n  overlay.firstElementChild.setAttribute('role', tone === 'neutral' ? 'status' : 'alert');\n  overlay.classList.add('open');\n  overlay.querySelector('button').focus();\n  return true;\n}\n\nfunction resume() {\n  if (state !== 'paused') {\n    return false;\n  }\n  overlay.classList.remove('open');\n  state = 'disconnected';\n  attemptConnected = true; // a person asked: start the retry budget over\n  requestTicket();\n  return true;\n}\n\nObject.defineProperty(window, 'orcaDesktop', {\n  value: Object.freeze({\n    version: 1,\n    state: () => state,\n    /** Resolves when the page needs a ticket: now if it is not connected, else after a drop. */\n    nextTicketRequest: () => new Promise((resolve) => {\n      ticketWaiters.push(resolve);\n      if (state === 'idle' || state === 'disconnected') {\n        requestTicket();\n      }\n    }),\n    connect,\n    paste,\n    pause,\n    resume\n  })\n});\n","orca-sandbox-grant":"#!/usr/bin/env bash\n# Mints a fresh, single-device orcad pairing offer for one org member's device and seals it to that\n# device's X25519 key, so the control plane relays only ciphertext (the VM owner's E2EE model holds:\n# every member device gets its own revocable orcad credential, nobody else can read it).\n# Env from the control plane: ORCA_GRANT_ID, ORCA_GRANT_RECIPIENT_KEY (base64 raw X25519 public\n# key), ORCA_GRANT_KIND (desktop|mobile), ORCA_PUBLIC_WSS. Prints one JSON line:\n# {\"deviceId\":\"…\",\"sealed\":{\"v\":1,\"ephemeralPublicKeyB64\":\"…\",\"nonceB64\":\"…\",\"ciphertextB64\":\"…\"}}\n# Sealing: ECDH(ephemeral, recipient) -> HKDF-SHA256(salt = eph||recipient, info\n# \"orca-cloud-grant-v1\") -> AES-256-GCM, AAD \"orca-cloud-grant-v1:<grant id>\".\nset -euo pipefail\numask 077\nORCA_HOME=/opt/orca\nSTATE=\"$HOME/.orca-sandbox\"\nDATA=\"$HOME/.orcad-data\"\nmkdir -p \"$STATE\"\nexec 9>\"$STATE/grant.lock\"\n# One mint at a time: --rotate retires unredeemed offers, so two members never share a credential.\nflock -w 30 9\n\ncase \"${ORCA_GRANT_ID:-}\" in '' | *[!A-Za-z0-9_-]*) echo 'bad grant id' >&2; exit 2 ;; esac\ncase \"${ORCA_GRANT_KIND:-}\" in desktop) scope=() ;; mobile) scope=(--mobile) ;; *) echo 'bad kind' >&2; exit 2 ;; esac\ncase \"${ORCA_GRANT_RECIPIENT_KEY:-}\" in '' | *[!A-Za-z0-9+/=]*) echo 'bad key' >&2; exit 2 ;; esac\ncase \"${ORCA_PUBLIC_WSS:-}\" in wss://*) ;; *) echo 'bad endpoint' >&2; exit 2 ;; esac\n\nnode=\"$(find \"$ORCA_HOME/runtime/runtimes\" -type f -name node | head -n 1)\"\ncli=\"$ORCA_HOME/runtime/orcad/out/cli/index.js\"\n# The workspace's project must exist on this orcad before a phone opens it: phones may not add\n# projects themselves (mobile RPC scope), and a phone may be the first client this VM ever sees.\nproject=/vercel/sandbox/project\nif [ -d \"$project\" ]; then\n  kind=folder\n  [ -d \"$project/.git\" ] && kind=git\n  ORCA_USER_DATA_PATH=\"$DATA\" timeout 20 \"$node\" \"$cli\" repo add --path \"$project\" --kind \"$kind\" --json \\\n    >/dev/null 2>&1 || true\nfi\noffer=\"$(ORCA_USER_DATA_PATH=\"$DATA\" timeout 30 \"$node\" \"$cli\" pair --json --rotate \"${scope[@]}\" \\\n  --address \"$ORCA_PUBLIC_WSS\" 2>/dev/null)\" || { echo 'pair failed' >&2; exit 1; }\n# The offer goes to the sealer on stdin (never argv or disk); only the sealed form is printed.\nprintf '%s' \"$offer\" | ORCA_GRANT_ID=\"$ORCA_GRANT_ID\" ORCA_GRANT_RECIPIENT_KEY=\"$ORCA_GRANT_RECIPIENT_KEY\" \\\n  \"$node\" -e '\nconst crypto = require(\"node:crypto\")\nlet input = \"\"\nprocess.stdin.on(\"data\", (c) => (input += c)).on(\"end\", () => {\n  const res = JSON.parse(input).result\n  if (!res || res.available !== true || !res.pairingUrl || !res.deviceId) {\n    console.error(\"offer unavailable\")\n    process.exit(1)\n  }\n  const recipient = Buffer.from(process.env.ORCA_GRANT_RECIPIENT_KEY, \"base64\")\n  if (recipient.length !== 32) { console.error(\"bad key length\"); process.exit(2) }\n  const recipientKey = crypto.createPublicKey({ key: { kty: \"OKP\", crv: \"X25519\", x: recipient.toString(\"base64url\") }, format: \"jwk\" })\n  const eph = crypto.generateKeyPairSync(\"x25519\")\n  const ephRaw = Buffer.from(eph.publicKey.export({ format: \"jwk\" }).x, \"base64url\")\n  const shared = crypto.diffieHellman({ privateKey: eph.privateKey, publicKey: recipientKey })\n  const key = Buffer.from(crypto.hkdfSync(\"sha256\", shared, Buffer.concat([ephRaw, recipient]), \"orca-cloud-grant-v1\", 32))\n  const nonce = crypto.randomBytes(12)\n  const cipher = crypto.createCipheriv(\"aes-256-gcm\", key, nonce)\n  cipher.setAAD(Buffer.from(\"orca-cloud-grant-v1:\" + process.env.ORCA_GRANT_ID))\n  const body = Buffer.from(JSON.stringify({ pairingUrl: res.pairingUrl, deviceId: res.deviceId, scope: res.scope }))\n  const ct = Buffer.concat([cipher.update(body), cipher.final(), cipher.getAuthTag()])\n  process.stdout.write(JSON.stringify({ deviceId: res.deviceId, sealed: { v: 1, ephemeralPublicKeyB64: ephRaw.toString(\"base64\"), nonceB64: nonce.toString(\"base64\"), ciphertextB64: ct.toString(\"base64\") } }) + \"\\n\")\n})'\n","orca-sandbox-revoke":"#!/usr/bin/env bash\n# Revokes member devices from orcad's device registry. orcad adopts on-disk removals at every auth\n# (an admin revoke, device-registry-store.ts), so this works whether or not orcad is running; the\n# control plane also runs it at boot, before orcad starts, for revokes queued while suspended.\n# Env: ORCA_REVOKE_DEVICE_IDS (comma list of orcad device ids). Prints {\"revoked\":<n>,\"live\":<n whose open sockets were closed>}.\nset -euo pipefail\numask 077\nSTATE=\"$HOME/.orca-sandbox\"\nREGISTRY=\"$HOME/.orcad-data/orca-devices.json\"\nmkdir -p \"$STATE\"\nexec 9>\"$STATE/grant.lock\"\nflock -w 30 9\n\nids=\"${ORCA_REVOKE_DEVICE_IDS:-}\"\ncase \"$ids\" in '' | *[!A-Za-z0-9,_-]*) echo 'bad device ids' >&2; exit 2 ;; esac\n# Live orcad first: `orca pair --revoke` also closes the device's open sockets now. Older orcad\n# builds lack it; the on-disk removal below still blocks their next sign-in.\nORCA_HOME=/opt/orca\nnode=\"$(find \"$ORCA_HOME/runtime/runtimes\" -type f -name node 2>/dev/null | head -n 1)\"\ncli=\"$ORCA_HOME/runtime/orcad/out/cli/index.js\"\nlive=0\nif [ -n \"$node\" ] && [ -f \"$cli\" ] && [ -s \"$HOME/.orcad-data/orca-runtime.json\" ]; then\n  for id in ${ids//,/ }; do\n    if ORCA_USER_DATA_PATH=\"$HOME/.orcad-data\" timeout 15 \"$node\" \"$cli\" pair --revoke \"$id\" --json 2>/dev/null \\\n      | jq -e '.ok == true and .result.revoked == true' >/dev/null 2>&1; then\n      live=$((live + 1))\n    fi\n  done\nfi\nif [ ! -s \"$REGISTRY\" ]; then\n  echo \"{\\\"revoked\\\":$live,\\\"live\\\":$live}\"\n  exit 0\nfi\nids_json=\"$(jq -cn --arg ids \"$ids\" '$ids | split(\",\") | map(select(length > 0))')\"\nbefore=\"$(jq 'length' \"$REGISTRY\")\"\ntmp=\"$(mktemp \"$REGISTRY.revoke.XXXXXX\")\"\n# Removes the rows and any phones delegated through them (parentDeviceId), like orcad's own revoke.\njq --argjson ids \"$ids_json\" \\\n  '[.[] | select((.deviceId as $d | $ids | index($d)) == null and ((.parentDeviceId // \"\") as $p | $ids | index($p)) == null)]' \\\n  \"$REGISTRY\" >\"$tmp\"\nchmod 0600 \"$tmp\"\nsync \"$tmp\" 2>/dev/null || true\nmv -f \"$tmp\" \"$REGISTRY\"\nafter=\"$(jq 'length' \"$REGISTRY\")\"\necho \"{\\\"revoked\\\":$((live + before - after)),\\\"live\\\":$live}\"\n","orca-sandbox-members":"#!/usr/bin/env bash\n# Runs as root (control plane, sudo). Installs who-may-push-as-whom for `orca-git-as`:\n#   /etc/orca/members/<member>.gitconfig  egress placeholder header + GitHub author identity\n#   /etc/orca/members/devices.json        {\"<orcad device id>\": \"<member id>\"} (each member's paired devices)\n# Both root-only: agents never read another member's placeholder. `orca-git-identity` (root, via a\n# sudoers rule) hands an agent only the identity of the member whose device drove its turn, as orcad\n# attests it. No token lives here: the placeholder is swapped at egress, for this repository only.\n# Env: ORCA_MEMBERS_B64 = base64 JSON [{userId, name, email, authorization, deviceIds:[...]}]\n# The VM user agents run as is orcad's own user (detected). Prints {\"members\":<n>,\"devices\":<n>}.\nset -euo pipefail\numask 077\nDIR=/etc/orca/members\norcad_pid=\"$(pgrep -f orcad-server.js | head -n 1 || true)\"\nUSER_NAME=\"$( [ -n \"$orcad_pid\" ] && ps -o user= -p \"$orcad_pid\" | tr -d ' ' || true)\"\nUSER_NAME=\"${USER_NAME:-${ORCA_SANDBOX_USER:-${SUDO_USER:-}}}\"\ncase \"$USER_NAME\" in '' | *[!a-z0-9_-]*) echo 'bad user' >&2; exit 2 ;; esac\nmkdir -p /etc/orca\njson=\"$(printf '%s' \"${ORCA_MEMBERS_B64:-W10=}\" | base64 -d)\"\ntmp=\"$(mktemp -d /etc/orca/members.XXXXXX)\"\ncount=0\nwhile IFS= read -r row; do\n  user=\"$(jq -r '.userId' <<<\"$row\")\"\n  case \"$user\" in '' | *[!A-Za-z0-9_.:-]*) continue ;; esac\n  file=\"$tmp/$(printf '%s' \"$user\" | tr ':' '_').gitconfig\"\n  # An empty extraheader first resets the image-wide (app identity) header for this member's git.\n  git config -f \"$file\" --add http.https://github.com/.extraheader ''\n  git config -f \"$file\" --add http.https://github.com/.extraheader \"Authorization: $(jq -r '.authorization' <<<\"$row\")\"\n  git config -f \"$file\" user.name \"$(jq -r '.name' <<<\"$row\")\"\n  git config -f \"$file\" user.email \"$(jq -r '.email' <<<\"$row\")\"\n  count=$((count + 1))\ndone < <(jq -c '.[]' <<<\"$json\")\njq -c '[.[] | select(.userId | test(\"^[A-Za-z0-9_.:-]+$\")) | .userId as $u | (.deviceIds // [])[] | select(test(\"^[A-Za-z0-9_-]{1,128}$\")) | {key: ., value: $u}] | from_entries' <<<\"$json\" >\"$tmp/devices.json\"\ndevices=\"$(jq 'length' \"$tmp/devices.json\")\"\nchmod 0700 \"$tmp\" && chmod 0600 \"$tmp\"/*\nrm -rf \"$DIR.old\"\n[ -d \"$DIR\" ] && mv \"$DIR\" \"$DIR.old\"\nmv \"$tmp\" \"$DIR\"\nrm -rf \"$DIR.old\"\n# Agents may ask for their own sender's identity, and only that (the helper checks with orcad).\nrule=\"$USER_NAME ALL=(root) NOPASSWD:SETENV: /opt/orca/bin/orca-git-identity\"\nprintf '%s\\n' \"$rule\" >/etc/sudoers.d/orca-git-identity.new\nchmod 0440 /etc/sudoers.d/orca-git-identity.new\nif visudo -cf /etc/sudoers.d/orca-git-identity.new >/dev/null; then\n  mv -f /etc/sudoers.d/orca-git-identity.new /etc/sudoers.d/orca-git-identity\nelse\n  rm -f /etc/sudoers.d/orca-git-identity.new\n  echo 'sudoers rule rejected' >&2\n  exit 1\nfi\n# Pre-attestation layout (agent-readable member files) must not linger.\nuser_home=\"$(getent passwd \"$USER_NAME\" | cut -d: -f6)\"\n[ -n \"$orcad_pid\" ] && user_home=\"$(tr '\\0' '\\n' <\"/proc/$orcad_pid/environ\" | sed -n 's/^HOME=//p' | head -n 1)\"\n[ -n \"$user_home\" ] && rm -rf \"$user_home/.orca-sandbox/members\"\n# Commits outside a teammate's turn still need an author (images older than orca-sandbox-start's default).\nif [ -n \"$user_home\" ]; then\n  sudo -u \"$USER_NAME\" env HOME=\"$user_home\" git config --global user.email >/dev/null 2>&1 \\\n    || sudo -u \"$USER_NAME\" env HOME=\"$user_home\" git config --global user.email 'cloud@users.noreply.onorca.dev'\n  sudo -u \"$USER_NAME\" env HOME=\"$user_home\" git config --global user.name >/dev/null 2>&1 \\\n    || sudo -u \"$USER_NAME\" env HOME=\"$user_home\" git config --global user.name 'Orca Cloud'\nfi\necho \"{\\\"members\\\":$count,\\\"devices\\\":$devices}\"\n","orca-git-as":"#!/usr/bin/env bash\n# Runs git as the teammate whose message started this agent's turn: their GitHub identity for\n# pushes/PRs (this repository only) and their commit author.\n#   orca-git-as <git args...>               e.g. orca-git-as push origin HEAD\n#   orca-git-as --as <member id> <git args>  refuses unless that member really sent the message\n# Orca attests the sender from the paired device that sent the message, never from arguments or\n# message text. Without an attested sender (not run from an agent, or the owner's local session) it\n# runs plain git with the workspace identity.\nset -euo pipefail\nexpect=''\nif [ \"${1:-}\" = '--as' ]; then\n  expect=\"${2:-}\"\n  shift 2 || { echo 'usage: orca-git-as [--as <member id>] <git args...>' >&2; exit 2; }\n  case \"$expect\" in '' | *[!A-Za-z0-9_.:-]*) echo 'orca-git-as: bad member id' >&2; exit 2 ;; esac\nfi\nset +e\nfile=\"$(ORCA_GIT_AS=\"$expect\" sudo -n --preserve-env=ORCA_GIT_AS,ORCA_TERMINAL_HANDLE,ORCA_PANE_KEY,ORCA_AGENT_LAUNCH_TOKEN,ORCA_AGENT_SESSION_ID \\\n  /opt/orca/bin/orca-git-identity)\"\nstatus=$?\nset -e\ncase \"$status\" in\n  0)\n    trap 'rm -f \"$file\"' EXIT\n    git -c \"include.path=$file\" \"$@\"\n    ;;\n  3)\n    echo 'orca-git-as: no teammate identity for this turn; using the workspace identity' >&2\n    exec git \"$@\"\n    ;;\n  *) exit 4 ;;\nesac\n","orca-git-identity":"#!/usr/bin/env bash\n# Root helper behind `orca-git-as` (sudoers: the VM user may run only this). Asks orcad, as the\n# calling agent, which paired device sent the message that started the agent's latest turn\n# (`orca sender`: orcad identifies the agent from its launch evidence, never from arguments), maps\n# that device to a workspace member, and prints that member's git config file for the caller to\n# include. Optional ORCA_GIT_AS: the member the agent expects; any other answer is refused.\n# Exit codes: 0 printed a config path; 3 no member identity (use the workspace identity); 4 refused.\nset -euo pipefail\nDIR=/etc/orca/members\ncaller=\"${SUDO_USER:-}\"\ncase \"$caller\" in '' | root | *[!a-z0-9_-]*) echo 'orca-git-identity: run through orca-git-as' >&2; exit 4 ;; esac\n# orcad's own data dir and HOME (the agent's user may not use its passwd home, e.g. HOME=/vercel).\norcad_pid=\"$(pgrep -u \"$caller\" -f orcad-server.js | head -n 1 || true)\"\n[ -n \"$orcad_pid\" ] || exit 3\norcad_env() { tr '\\0' '\\n' <\"/proc/$orcad_pid/environ\" | sed -n \"s/^$1=//p\" | head -n 1; }\nhome=\"$(orcad_env HOME)\"\ndata=\"$(orcad_env ORCA_USER_DATA)\"\ndata=\"${data:-$home/.orcad-data}\"\nnode=\"$(find /opt/orca/runtime/runtimes -type f -name node | head -n 1)\"\ncli=/opt/orca/runtime/orcad/out/cli/index.js\n# Only the evidence variables orcad needs reach the query, which runs as the caller, not root.\nanswer=\"$(sudo -u \"$caller\" env -i HOME=\"$home\" PATH=/usr/bin:/bin ORCA_USER_DATA_PATH=\"$data\" \\\n  ${ORCA_TERMINAL_HANDLE:+ORCA_TERMINAL_HANDLE=\"$ORCA_TERMINAL_HANDLE\"} \\\n  ${ORCA_PANE_KEY:+ORCA_PANE_KEY=\"$ORCA_PANE_KEY\"} \\\n  ${ORCA_AGENT_LAUNCH_TOKEN:+ORCA_AGENT_LAUNCH_TOKEN=\"$ORCA_AGENT_LAUNCH_TOKEN\"} \\\n  ${ORCA_AGENT_SESSION_ID:+ORCA_AGENT_SESSION_ID=\"$ORCA_AGENT_SESSION_ID\"} \\\n  timeout 15 \"$node\" \"$cli\" sender --json 2>/dev/null || true)\"\ndevice=\"$(jq -r '.result.sender.deviceId // empty' <<<\"$answer\" 2>/dev/null || true)\"\nif [ -z \"$device\" ] || [ ! -s \"$DIR/devices.json\" ]; then\n  if [ -n \"${ORCA_GIT_AS:-}\" ]; then\n    echo \"orca-git-as: Orca cannot confirm that $ORCA_GIT_AS sent this agent's latest message; refusing to push as them.\" >&2\n    exit 4\n  fi\n  exit 3\nfi\nmember=\"$(jq -r --arg d \"$device\" '.[$d] // empty' \"$DIR/devices.json\")\"\nif [ -z \"$member\" ]; then\n  [ -n \"${ORCA_GIT_AS:-}\" ] && { echo \"orca-git-as: the sender's device is not linked to a workspace member; refusing.\" >&2; exit 4; }\n  exit 3\nfi\nif [ -n \"${ORCA_GIT_AS:-}\" ] && [ \"$ORCA_GIT_AS\" != \"$member\" ]; then\n  echo \"orca-git-as: this agent's latest message came from $member, not $ORCA_GIT_AS; refusing to push as someone else.\" >&2\n  exit 4\nfi\nfile=\"$DIR/$(printf '%s' \"$member\" | tr ':' '_').gitconfig\"\n[ -s \"$file\" ] || exit 3\n# The caller reads the identity through this one-shot copy (owned by them, removed by orca-git-as).\nout=\"$(sudo -u \"$caller\" mktemp)\"\ncat \"$file\" >\"$out\"\necho \"$out\"\n","git":"#!/usr/bin/env bash\n# git for agents in Orca Cloud workspaces (first on orcad's PATH). Commands that author or publish\n# work run as the teammate whose message started this agent's turn (orca-git-as: orcad attests the\n# sender's paired device; root-only member identities). Everything else is plain git, untouched.\nreal=/usr/bin/git\nsub=''\nskip=0\nfor arg in \"$@\"; do\n  if [ \"$skip\" = 1 ]; then skip=0; continue; fi\n  case \"$arg\" in\n    -C | -c | --git-dir | --work-tree | --namespace | --exec-path | --config-env) skip=1 ;;\n    -*) ;;\n    *) sub=\"$arg\"; break ;;\n  esac\ndone\ncase \"$sub\" in\n  commit | push | merge | rebase | cherry-pick | revert | am | pull | tag)\n    # Outside an agent turn (no attested sender) orca-git-as falls back to the workspace identity.\n    if [ -n \"${ORCA_TERMINAL_HANDLE:-}${ORCA_AGENT_SESSION_ID:-}\" ] && [ -x /opt/orca/bin/orca-git-as ]; then\n      PATH=\"/usr/bin:/bin:$PATH\" exec /opt/orca/bin/orca-git-as \"$@\" 2> >(grep -v '^orca-git-as: no teammate identity' >&2)\n    fi\n    ;;\nesac\nexec \"$real\" \"$@\"\n"}
export const SOURCE_BUILD_SCRIPT: string = "#!/usr/bin/env bash\n# Golden build from source, run by the Worker inside the build sandbox: orcad + the orca CLI from one\n# commit of the Orca repo (cloud/integration carries host RPCs no upstream release has), then the same\n# provision-golden.sh every image uses. Inputs (env):\n#   ORCA_SRC_SHA (40-hex) and either ORCA_SRC_DIR (source already uploaded) or ORCA_SRC_REPO\n#   (https://github.com/<owner>/<repo>) + ORCA_SRC_AUTH (an\n#   `Authorization: Basic …` header value for a 1 h read-only installation token; never printed),\n#   ORCA_PROVISION_SCRIPT (base64 of provision-golden.sh) + everything provision-golden.sh reads.\nset -euo pipefail\n# Vercel can report a detached build command as still running after it exits, so the outcome is also\n# a file the caller polls: /tmp/source-build.exit (exit code), /tmp/source-build.report (the\n# provision report line).\nrm -f /tmp/source-build.exit /tmp/source-build.report\ntrap 'echo $? >/tmp/source-build.exit' EXIT\nlog() { printf '[source-build] %s\\n' \"$*\" >&2; }\nstart=$(date +%s)\n[[ \"$ORCA_SRC_SHA\" =~ ^[0-9a-f]{40}$ ]] || { log 'ORCA_SRC_SHA must be a full commit sha'; exit 2; }\n\nlog 'build tools'\nif command -v apt-get >/dev/null; then\n  # Transient mirror errors and dpkg lock contention made apt exit 100 (2 of ~10 golden builds):\n  # retry downloads and wait for the lock instead of failing the build.\n  printf 'Acquire::Retries \"5\";\\nDPkg::Lock::Timeout \"180\";\\n' | sudo tee /etc/apt/apt.conf.d/80-orca-retries >/dev/null\n  sudo apt-get update -qq\n  sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends build-essential python3 git ca-certificates >/dev/null\nelse\n  sudo dnf install -y -q gcc gcc-c++ make tar gzip python3 git >/dev/null\nfi\nsudo corepack enable >/dev/null 2>&1 || true\n\nsrc=\"$HOME/orca-src\"\nif [ -n \"${ORCA_SRC_DIR:-}\" ]; then\n  # Operator rotation (image/rotate-golden-from-source.ts) uploaded `git archive <sha>` here already.\n  log \"uploaded source for $ORCA_SRC_SHA\"\n  src=\"$ORCA_SRC_DIR\"\n  cd \"$src\" && test -f package.json\n  git init -q && git add -A && git -c user.email=build@orca -c user.name=build commit -qm \"$ORCA_SRC_SHA\"\nelse\n  log \"fetch $ORCA_SRC_SHA\"\n  rm -rf \"$src\" && mkdir -p \"$src\" && cd \"$src\"\n  git init -q\n  # The header lives only in this one command's config, not in .git/config.\n  git -c \"http.https://github.com/.extraheader=$ORCA_SRC_AUTH\" fetch -q --depth 1 \"$ORCA_SRC_REPO\" \"$ORCA_SRC_SHA\"\n  unset ORCA_SRC_AUTH\n  git -c advice.detachedHead=false checkout -q FETCH_HEAD\n  test \"$(git rev-parse HEAD)\" = \"$ORCA_SRC_SHA\"\nfi\n\n# The image files come from this commit too (VM scripts, provision, manifest pins). The env the\n# caller passed is only a fallback for commits from before commit-provision-env.mjs existed.\nimage_dir=\"$src/cloud/apps/sandbox-control/image\"\nif [ -f \"$image_dir/commit-provision-env.mjs\" ]; then\n  node \"$image_dir/commit-provision-env.mjs\" \"$image_dir\" >/tmp/commit-provision.env\n  # shellcheck disable=SC1091\n  . /tmp/commit-provision.env\n  rm -f /tmp/commit-provision.env\n  log \"image files from $ORCA_SRC_SHA\"\nfi\n\nlog 'build orcad + CLI'\nexport CI=1 ELECTRON_SKIP_BINARY_DOWNLOAD=1 PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1\ncorepack pnpm install --frozen-lockfile >/tmp/src-install.log 2>&1 || { tail -40 /tmp/src-install.log >&2; exit 1; }\ncorepack pnpm -C mobile install --frozen-lockfile >/tmp/src-mobile.log 2>&1 || { tail -40 /tmp/src-mobile.log >&2; exit 1; }\ncorepack pnpm build:mobile-web >/tmp/src-mobile-web.log 2>&1 || { tail -40 /tmp/src-mobile-web.log >&2; exit 1; }\ncorepack pnpm build:orcad >/tmp/src-orcad.log 2>&1 || { tail -60 /tmp/src-orcad.log >&2; exit 1; }\ncorepack pnpm build:cli >/tmp/src-cli.log 2>&1 || { tail -40 /tmp/src-cli.log >&2; exit 1; }\nmkdir -p out/orca-cli\nnode_modules/.bin/esbuild out/cli/index.js --bundle --platform=node --target=node22 --format=cjs \\\n  --outfile=out/orca-cli/orca-cli.cjs --log-level=error\nprintf '%s\\n' \"$ORCA_SRC_SHA\" >out/orcad/SOURCE_COMMIT\ntar czf /tmp/orcad.tgz -C out orcad runtimes orca-cli\nlog \"built in $(( $(date +%s) - start ))s\"\n\nexport ORCAD_BUNDLE_URL=file:///tmp/orcad.tgz\nORCAD_BUNDLE_SHA256=\"$(sha256sum /tmp/orcad.tgz | cut -d' ' -f1)\"\nexport ORCAD_BUNDLE_SHA256\ncd \"$HOME\"\nprintf '%s' \"$ORCA_PROVISION_SCRIPT\" | base64 -d >/tmp/provision-golden.sh\nunset ORCA_PROVISION_SCRIPT\nbash /tmp/provision-golden.sh | tee /tmp/source-build.report\n# Build leftovers stay out of the image.\nrm -rf \"$src\" \"$HOME/.local/share/pnpm\" \"$HOME/.cache/pnpm\" /tmp/orcad.tgz /tmp/provision-golden.sh /tmp/src-*.log\nlog \"done in $(( $(date +%s) - start ))s\"\n"
export const ENVIRONMENT_BUILD_SCRIPT: string = "#!/usr/bin/env bash\n# Environment build (\"Cloud Computer\"), run by the control plane in a VM booted from the golden image.\n# Clones every repo, runs the org's install script once with `set -euo pipefail`, then records what it\n# built from (commit + lockfile blob ids per repo) so the control plane can tell when a rebuild is due.\n# Everything printed here streams live to the desktop build log.\n#\n# Env from the control plane (validated there): ORCA_BUILD_REPOS (`<url>|<branch or empty>|<dir>|\n# <git auth header or empty>` lines: each private repo gets its own placeholder the egress swaps), ORCA_INSTALL_SCRIPT_B64, ORCA_LOCKFILES (space list), optional ORCA_GIT_EXTRAHEADER, plus\n# the org secrets the environment names. `::orca-step:: <name>` lines mark progress.\n# Exit codes: 10 clone, 20 install script, 30 recording the result.\nset -uo pipefail\numask 022\n# One stream: the provider replays stdout and stderr separately after the fact, so a failed build's\n# log would read out of order. `::orca-error::` lines carry Orca's own failure explanations.\nexec 2>&1\nOUT=/tmp/orca-build\nROOT=/vercel/sandbox/repos\nmkdir -p \"$OUT\" \"$ROOT\"\nstep() { printf '\\n::orca-step:: %s\\n' \"$1\"; }\nstarted=$(date +%s)\nexport PATH=\"/opt/orca/tools/bin:/opt/orca/bin:$PATH\"\nexport ORCA_REPOS_ROOT=\"$ROOT\" ORCA_ENVIRONMENT_BUILD=1 CI=1 GIT_TERMINAL_PROMPT=0\nrepos() { printf '%s\\n' \"$ORCA_BUILD_REPOS\"; }\n\n# Tell the script author (often an agent) what they are installing onto.\npm=$(for c in apt-get dnf yum apk; do command -v \"$c\" >/dev/null 2>&1 && { echo \"$c\"; break; }; done)\necho \"Base image: $(. /etc/os-release 2>/dev/null && echo \"$PRETTY_NAME\"), $(nproc) vCPU, package manager: ${pm:-none} (with sudo)\"\n\nstep clone\nfirst=\"\"\nwhile IFS='|' read -r url branch dir header; do\n  [ -n \"$url\" ] || continue\n  dest=\"$ROOT/$dir\"\n  [ -n \"$first\" ] || first=\"$dest\"\n  # The egress layer swaps the placeholder for a short-lived repo token; nothing real is on disk,\n  # and the header is never written to the repo's config.\n  git_auth=()\n  [ -z \"${header:-}\" ] || git_auth=(-c \"http.https://github.com/.extraheader=$header\")\n  echo \"Cloning $url${branch:+ ($branch)}\"\n  rm -rf -- \"$dest\"\n  # The clone's own error shows only when it really failed (an empty repo is recovered below).\n  if ! git \"${git_auth[@]}\" clone --quiet ${branch:+--branch \"$branch\"} -- \"$url\" \"$dest\" 2>\"$OUT/clone.err\"; then\n    refs=0\n    git \"${git_auth[@]}\" ls-remote --exit-code -- \"$url\" >/dev/null 2>&1 || refs=$?\n    if [ -n \"$branch\" ] && [ \"$refs\" -eq 2 ]; then\n      # Reachable but no refs at all (ls-remote exits 2): a repo with no commits yet.\n      echo \"$url has no commits yet; starting it empty on $branch.\"\n      rm -rf -- \"$dest\"\n      { git \"${git_auth[@]}\" clone --quiet -- \"$url\" \"$dest\" 2>/dev/null && git -C \"$dest\" checkout --quiet -b \"$branch\"; } || exit 10\n    else\n      cat \"$OUT/clone.err\"\n      echo \"::orca-error:: Could not clone $url${branch:+ at $branch}. Check that the branch exists and Orca Cloud can reach the repository.\" \n      exit 10\n    fi\n  fi\n  git -C \"$dest\" log -1 --format='  at %h %s' 2>/dev/null || echo '  (no commits yet)'\ndone < <(repos)\n\nstep install\nprintf '%s' \"${ORCA_INSTALL_SCRIPT_B64:-}\" | base64 -d >\"$OUT/install.sh\"\nif [ -s \"$OUT/install.sh\" ]; then\n  echo \"Running the install script in ${first:-$ROOT}\"\n  (cd \"${first:-$ROOT}\" && exec bash -euo pipefail \"$OUT/install.sh\") </dev/null\n  rc=$?\n  if [ \"$rc\" -ne 0 ]; then\n    echo \"::orca-error:: The install script exited with status $rc.\" \n    exit 20\n  fi\nelse\n  echo \"No install script; the build keeps the cloned repos.\"\nfi\n\nstep record\n# New workspaces are linked worktrees of these checkouts: list the dependency folders the install\n# produced and add a post-checkout hook that hard-links them into each new worktree.\n# Python virtualenvs are left out on purpose: their scripts and editable installs embed the primary\n# checkout's absolute path, so a linked copy would run the wrong source.\ndeps_re='(^|/)(node_modules|vendor/bundle|\\.bundle|bower_components|\\.yarn/cache|\\.pnpm-store)/?$|(^|/)\\.env[^/]*$'\nwhile IFS='|' read -r url branch dir _; do\n  [ -n \"$url\" ] || continue\n  dest=\"$ROOT/$dir\"\n  common=\"$(git -C \"$dest\" rev-parse --path-format=absolute --git-common-dir 2>/dev/null)\" || continue\n  git -C \"$dest\" ls-files --others --ignored --exclude-standard --directory 2>/dev/null \\\n    | sed 's#/$##' | grep -E \"$deps_re\" | head -n 500 >\"$common/orca-env-deps\" || true\n  if [ -n \"${ORCA_DEPS_HOOK_B64:-}\" ]; then\n    # A relative core.hooksPath (husky: .husky/_) names a gitignored folder a new worktree lacks; pin\n    # it to the primary checkout so every worktree runs the same hooks, ours included.\n    rel=\"$(git -C \"$dest\" config --get core.hooksPath 2>/dev/null || true)\"\n    case \"$rel\" in '' | /*) ;; *) git -C \"$dest\" config core.hooksPath \"$dest/$rel\" ;; esac\n    hooks=\"$(git -C \"$dest\" rev-parse --path-format=absolute --git-path hooks)\"\n    mkdir -p \"$hooks\"\n    if [ -e \"$hooks/post-checkout\" ] && ! grep -q 'orca-env-deps' \"$hooks/post-checkout\"; then\n      mv -- \"$hooks/post-checkout\" \"$hooks/post-checkout.orca-chained\"\n    fi\n    printf '%s' \"$ORCA_DEPS_HOOK_B64\" | base64 -d >\"$hooks/post-checkout\" && chmod 0755 \"$hooks/post-checkout\"\n  fi\n  n=$(wc -l <\"$common/orca-env-deps\" | tr -d ' ')\n  [ \"$n\" -gt 0 ] && echo \"$dir: $n installed folder(s) carried into new workspaces.\"\ndone < <(repos)\n{\n  printf '{\"durationSec\":%d,\"repos\":[' \"$(( $(date +%s) - started ))\"\n  sep=\"\"\n  while IFS='|' read -r url branch dir _; do\n    [ -n \"$url\" ] || continue\n    dest=\"$ROOT/$dir\"\n    commit=$(git -C \"$dest\" rev-parse --verify --quiet HEAD 2>/dev/null || true)\n    head=$(git -C \"$dest\" symbolic-ref --quiet --short HEAD 2>/dev/null || true)\n    printf '%s{\"url\":\"%s\",\"dir\":\"%s\",\"branch\":\"%s\",\"commit\":\"%s\",\"lockfiles\":{' \"$sep\" \"$url\" \"$dir\" \"$head\" \"$commit\"\n    lsep=\"\"\n    if [ -n \"$commit\" ]; then\n      for f in ${ORCA_LOCKFILES:-}; do\n        blob=$(git -C \"$dest\" rev-parse --verify --quiet \"HEAD:$f\" 2>/dev/null || true)\n        if [ -n \"$blob\" ]; then printf '%s\"%s\":\"%s\"' \"$lsep\" \"$f\" \"$blob\"; lsep=\",\"; fi\n      done\n    fi\n    printf '}}'\n    sep=\",\"\n  done < <(repos)\n  printf '],\"diskUsedBytes\":%s,\"diskTotalBytes\":%s}\\n' \\\n    \"$(df -B1 --output=used / | tail -n 1 | tr -d ' ')\" \"$(df -B1 --output=size / | tail -n 1 | tr -d ' ')\"\n} >\"$OUT/result.json\" || exit 30\n# Nothing from this VM's own session belongs in the image, only what the script installed.\nrm -rf -- \"$OUT/install.sh\" \"$HOME/.bash_history\" \"$HOME/.orcad-data\" \"$HOME/.orca-sandbox\"\necho \"Disk used: $(df -h --output=used / | tail -n 1 | tr -d ' ') of $(df -h --output=size / | tail -n 1 | tr -d ' ')\"\n"
export const ENVIRONMENT_DEPS_HOOK: string = "#!/usr/bin/env bash\n# Installed by Orca environment builds as the repo's post-checkout hook. When git creates a new linked\n# worktree (`git worktree add` passes the null commit as the previous HEAD), give it the dependency\n# folders the build installed in the primary checkout, as hard links: near-instant, real paths (not\n# symlinks, so bundlers and native modules behave). Hard links share file contents: tools that rewrite\n# a file in place inside these folders change it for every worktree on this VM (one workspace per VM).\n# Any post-checkout hook the repo already had runs afterwards, unchanged.\nprev=\"${1:-}\"\nhere=\"$(dirname \"$0\")\"\nif [ \"$prev\" = \"0000000000000000000000000000000000000000\" ] && [ \"${ORCA_SKIP_DEPS_LINK:-}\" != 1 ]; then\n  common=\"$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null || true)\"\n  top=\"$(git rev-parse --show-toplevel 2>/dev/null || true)\"\n  primary=\"$(dirname \"$common\")\"\n  list=\"$common/orca-env-deps\"\n  if [ -n \"$top\" ] && [ \"$top\" != \"$primary\" ] && [ -f \"$list\" ]; then\n    started=$(date +%s%N)\n    linked=0\n    while IFS= read -r rel; do\n      case \"$rel\" in '' | /* | *..*) continue ;; esac\n      [ -e \"$primary/$rel\" ] && [ ! -e \"$top/$rel\" ] || continue\n      mkdir -p \"$(dirname \"$top/$rel\")\"\n      if [ -d \"$primary/$rel\" ]; then\n        if ! cp -al -- \"$primary/$rel\" \"$top/$rel\" 2>/dev/null; then\n          # A partial hard-link copy would make the fallback nest inside it: start clean.\n          rm -rf -- \"$top/$rel\"\n          cp -a -- \"$primary/$rel\" \"$top/$rel\" 2>/dev/null || { rm -rf -- \"$top/$rel\"; continue; }\n        fi\n      else\n        cp -a -- \"$primary/$rel\" \"$top/$rel\" 2>/dev/null || continue\n      fi\n      linked=$((linked + 1))\n    done <\"$list\"\n    if [ \"$linked\" -gt 0 ]; then\n      echo \"Orca: reused $linked installed dependency folder(s) from the environment build ($(( ($(date +%s%N) - started) / 1000000 )) ms).\" >&2\n    fi\n  fi\nfi\nif [ -x \"$here/post-checkout.orca-chained\" ]; then\n  if head -n 1 \"$here/post-checkout.orca-chained\" | grep -Eq '^#!.*(ba|da|z)?sh'; then\n    # Sourced, so $0 still names `post-checkout` (husky v9 finds the user's hook by basename \"$0\").\n    ( . \"$here/post-checkout.orca-chained\" \"$@\" )\n    exit $?\n  fi\n  exec \"$here/post-checkout.orca-chained\" \"$@\"\nfi\nexit 0\n"
export const WORKSPACE_PRELUDE_SCRIPT: string = "#!/usr/bin/env bash\n# Runs right before orca-sandbox-start on a workspace's first boot. Prints only to stderr: the start\n# script's last stdout line is the orcad recipe line the control plane parses.\n#\n# - Booted from an environment build (ORCA_ENV_REPO_DIR set): the repo is already cloned with its\n#   dependencies installed under /vercel/sandbox/repos. Link it as the project (a link, not a move,\n#   so absolute paths baked into installed dependencies keep working). No fetch when the build is\n#   already on the requested branch: Orca fetches the base right before it adds the workspace's\n#   worktree, so a fetch here would only delay orcad (measured ~0.5-1 s). Another branch is fetched\n#   and checked out; if that fails the workspace still opens at the build's commit.\n# - Otherwise clone ORCA_REPO_URL here so a repo with no commits yet also opens: it gets an empty\n#   first commit on the requested branch, which Orca needs to create the workspace's worktree.\nset -uo pipefail\nP=/vercel/sandbox/project\nROOT=/vercel/sandbox/repos\nexport GIT_TERMINAL_PROMPT=0\nauth=()\nif [ -n \"${ORCA_GIT_EXTRAHEADER:-}\" ]; then\n  auth=(-c \"http.https://github.com/.extraheader=$ORCA_GIT_EXTRAHEADER\")\nfi\nref=\"${ORCA_REPO_REF:-}\"\n\nfirst_commit() {\n  if ! git -C \"$P\" rev-parse --verify --quiet HEAD >/dev/null; then\n    git -C \"$P\" checkout --quiet -B \"${ref:-main}\" 2>/dev/null || true\n    git -C \"$P\" -c user.name='Orca' -c user.email='cloud@onorca.dev' \\\n      commit --quiet --allow-empty -m 'Initial commit' && echo 'Empty repository: created a first commit.'\n  fi\n}\n\nif [ ! -e \"$P\" ] && [ -n \"${ORCA_ENV_REPO_DIR:-}\" ] && [ -d \"$ROOT/$ORCA_ENV_REPO_DIR/.git\" ]; then\n  ln -s \"$ROOT/$ORCA_ENV_REPO_DIR\" \"$P\"\n  if [ -n \"$ref\" ] && [ \"$(git -C \"$P\" symbolic-ref --quiet --short HEAD 2>/dev/null)\" != \"$ref\" ]; then\n    if timeout 60 git \"${auth[@]}\" -C \"$P\" fetch --quiet origin \"+refs/heads/$ref:refs/remotes/origin/$ref\"; then\n      # -f: the install may have rewritten tracked files (a lockfile); the branch's version wins.\n      git -C \"$P\" checkout --quiet -f -B \"$ref\" \"origin/$ref\" -- ||\n        echo \"Could not switch to $ref; the workspace starts at the build's commit.\"\n    else\n      echo \"Could not fetch $ref; the workspace starts at the build's commit.\"\n    fi\n  fi\n  first_commit\nelif [ ! -e \"$P\" ] && [ -n \"${ORCA_REPO_URL:-}\" ]; then\n  if ! git \"${auth[@]}\" clone --quiet ${ref:+--branch \"$ref\"} -- \"$ORCA_REPO_URL\" \"$P\" 2>/dev/null; then\n    rm -rf -- \"$P\"\n    # Branch missing (or a repo with no commits): clone the default branch, then switch.\n    git \"${auth[@]}\" clone --quiet -- \"$ORCA_REPO_URL\" \"$P\" || exit 1\n    if [ -n \"$ref\" ] && ! git -C \"$P\" checkout --quiet \"$ref\" -- 2>/dev/null; then\n      git -C \"$P\" checkout --quiet -b \"$ref\" -- || true\n    fi\n  fi\n  first_commit\nfi\nexit 0\n"
